class LRUCache:
    """Least-recently-used cache. get() and put() both count as use. When put() would exceed capacity, evict the least recently used key. get() of a missing key returns None. capacity < 1 raises ValueError."""

    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.data = {}
        # Use a list to track access order: index 0 is least recently used, end is most recently used
        self.order = []

    def _update_access(self, key):
        """Move key to the end of the order list to mark it as most recently used."""
        if key in self.order:
            self.order.remove(key)
        self.order.append(key)

    def get(self, key):
        if key not in self.data:
            return None
        self._update_access(key)
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self._update_access(key)
        else:
            if len(self.data) >= self.capacity:
                # Evict the least recently used key (first in order list)
                lru_key = self.order.pop(0)
                del self.data[lru_key]
            self.order.append(key)

        self.data[key] = value
```

The bug is that `get()` does not update the recency of the key, so a recently-read item can be evicted prematurely. The fix is to track access order explicitly and move a key to the "most recently used" position on both `get()` and `put()`.

```python
class LRUCache:
    """Least-recently-used cache. get() and put() both count as use. When put() would exceed capacity, evict the least recently used key. get() of a missing key returns None. capacity < 1 raises ValueError."""

    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.data = {}
        self.order = []  # list of keys, least-recently-used at index 0

    def _touch(self, key):
        # Move key to the end (most recently used)
        self.order.remove(key)
        self.order.append(key)

    def get(self, key):
        if key not in self.data:
            return None
        self._touch(key)
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self.data[key] = value
            self._touch(key)
        else:
            if len(self.data) >= self.capacity:
                # Evict least recently used
                lru_key = self.order.pop(0)
                del self.data[lru_key]
            self.data[key] = value
            self.order.append(key)
