def deep_merge(base, override):
    """Return a new dict with the keys of both. When both values for a key are dicts they are merged recursively; otherwise the override value wins (even None). Neither input is modified, and the result shares no mutable dict or list with either input."""
    result = {}

    # Copy base keys first, ensuring deep copies of mutable structures
    for k, v in base.items():
        if isinstance(v, dict):
            result[k] = deep_merge(v, {})
        elif isinstance(v, list):
            result[k] = list(v)
        else:
            result[k] = v

    # Apply overrides
    for k, v in override.items():
        if isinstance(v, dict) and isinstance(result.get(k), dict):
            result[k] = deep_merge(result[k], v)
        elif isinstance(v, list) and isinstance(result.get(k), list):
            # If both are lists, override wins per "otherwise the override value wins"
            # but we must ensure we don't share the list reference if we were keeping base logic.
            # Since override wins, we just take the value, but ensure we don't mutate input.
            # The docstring says result shares no mutable list with input.
            # If we just assign result[k] = v, we share reference with override.
            # So we must copy the list from override too.
            result[k] = list(v)
        else:
            # Override wins (even if None)
            # If v is a list, we must copy it to avoid sharing reference with override
            if isinstance(v, list):
                result[k] = list(v)
            elif isinstance(v, dict):
                # Case where base didn't have this key or wasn't a dict, but override is dict
                result[k] = deep_merge(v, {})
            else:
                result[k] = v

    return result
