The bug is that `json.dumps` does not sort dictionary keys by default, so `kwargs` with different insertion orders produce different JSON strings. Additionally, `json.dumps` converts both lists and tuples to JSON arrays, so `[1, 2]` and `(1, 2)` produce identical output.

To fix this:
1. Use `sort_keys=True` in `json.dumps` to ensure consistent ordering of dictionary keys.
2. Create a custom serialization function that distinguishes between lists and tuples by tagging them differently before serialization.

```python
import json


def _normalize_for_cache(value):
    """Recursively normalize a value for cache key generation.

    Lists are wrapped as ['__list__', ...], tuples as ['__tuple__', ...],
    and dicts have their keys sorted. This ensures type distinction and
    consistent ordering.
    """
    if value is None or isinstance(value, bool):
        # bool must be checked before int because bool is a subclass of int
        return value
    elif isinstance(value, int):
        return value
    elif isinstance(value, float):
        return value
    elif isinstance(value, str):
        return value
    elif isinstance(value, list):
        return ['__list__', [_normalize_for_cache(item) for item in value]]
    elif isinstance(value, tuple):
        return ['__tuple__', [_normalize_for_cache(item) for item in value]]
    elif isinstance(value, dict):
        # Validate all keys are strings
        for key in value.keys():
            if not isinstance(key, str):
                raise TypeError(f"Dict keys must be strings, got {type(key).__name__}")
        # Sort keys and normalize values
        return {k: _normalize_for_cache(v) for k, v in sorted(value.items())}
    else:
        raise TypeError(f"Unsupported type for cache key: {type(value).__name__}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""
    normalized_args = tuple(_normalize_for_cache(arg) for arg in args)
    normalized_kwargs = {k: _normalize_for_cache(v) for k, v in kwargs.items()}
    return json.dumps([normalized_args, normalized_kwargs], sort_keys=True)
```

```python
def parse_int(text, default=None):
    """Parse a human-entered integer. Accepts surrounding whitespace, an optional leading + or -, and ASCII digits, optionally with thousands commas in correct groups of three ('1,234', '-12,345,678'). Returns `default` for anything else: empty text, '1,23', '1,,234', ',5', '12.5', '1e3', '1_000', non-ASCII digits, a bare sign, or a non-string argument."""
    if not isinstance(text, str):
        return default

    # Strip surrounding whitespace
    s = text.strip()

    if not s:
        return default

    # Handle optional leading sign
    sign = 1
    if s[0] == '+':
        s = s[1:]
    elif s[0] == '-':
        sign = -1
        s = s[1:]

    # After removing sign, if empty, it was a bare sign
    if not s:
        return default

    # Split by commas to validate grouping
    parts = s.split(',')

    # Validate comma grouping:
    # 1. The first part (leftmost) can be 1 to 3 digits.
    # 2. All subsequent parts must be exactly 3 digits.
    # 3. No empty parts (handles leading/trailing commas or double commas like "1,,2")

    if len(parts) == 1:
        # No commas: just check if it's all ASCII digits
        if not parts[0].isdigit() or not all(c in '0123456789' for c in parts[0]):
            return default
        # Check for non-ASCII digits just in case (isdigit() allows some unicode)
        # The prompt specifies ASCII digits only.
        if not all('0' <= c <= '9' for c in parts[0]):
            return default
    else:
        # Multiple parts due to commas
        # First part must be 1-3 digits
        first = parts[0]
        if not (1 <= len(first) <= 3):
            return default
        if not first.isdigit() or not all('0' <= c <= '9' for c in first):
            return default

        # Remaining parts must be exactly 3 digits each
        for part in parts[1:]:
            if len(part) != 3:
                return default
            if not part.isdigit() or not all('0' <= c <= '9' for c in part):
                return default

    # If we get here, the format is valid. Reconstruct the digit string.
    digit_str = ''.join(parts)

    try:
        return sign * int(digit_str)
    except ValueError:
        return default
