def moving_average(xs, k):
    """Mean of each full window of k consecutive values (len(xs) - k + 1 results). Empty list if k > len(xs). k < 1 raises ValueError."""
    if k < 1:
        raise ValueError("k must be at least 1")
    out = []
    for i in range(len(xs) - k + 1):
        out.append(sum(xs[i:i + k]) / k)
    return out
