import json


def _normalize(value):
    """Recursively normalize a value into a hashable, order-independent structure.

    - None, bool, int, float, str: return as-is (bool must be checked before int)
    - list: convert to tuple of normalized items
    - tuple: convert to tuple of normalized items
    - dict: check all keys are str, then return frozenset of (key, normalized_value) pairs

    Raises TypeError for unsupported types or dicts with non-str keys.
    """
    # Check bool before int because bool is a subclass of int
    if value is None or isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return value
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        return tuple(_normalize(item) for item in value)
    if isinstance(value, tuple):
        return tuple(_normalize(item) for item in value)
    if isinstance(value, dict):
        for key in value:
            if not isinstance(key, str):
                raise TypeError(f"Dict keys must be str, got {type(key).__name__}")
        return frozenset((k, _normalize(v)) for k, v in value.items())
    raise TypeError(f"Unsupported type: {type(value).__name__}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""
    normalized_args = tuple(_normalize(arg) for arg in args)
    normalized_kwargs = {k: _normalize(v) for k, v in kwargs.items()}
