class LRUCache:
    """Least-recently-used cache. get() and put() both count as use. When put() would exceed capacity, evict the least recently used key. get() of a missing key returns None. capacity < 1 raises ValueError."""

    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self.data = {}

    def get(self, key):
        if key not in self.data:
            return None
        # Move key to the end to mark it as most recently used
        value = self.data.pop(key)
        self.data[key] = value
        return value

    def put(self, key, value):
        if key in self.data:
            # Remove existing key to re-insert it at the end (mark as used)
            self.data.pop(key)

        self.data[key] = value

        if len(self.data) > self.capacity:
            # Evict the least recently used key (the first one in insertion order)
            lru_key = next(iter(self.data))
            self.data.pop(lru_key)
