The bug exists because `json.dumps` preserves the order of Python tuples and lists as given, and does not normalize dictionary key order in older Python versions (though modern Python dicts are ordered, `json.dumps` doesn't sort keys by default). More critically:

1. `cache_key(a=1, b=2)` produces `json.dumps([(,), {"a": 1, "b": 2}])` 
2. `cache_key(b=2, a=1)` produces `json.dumps([(,), {"b": 2, "a": 1}])`

These are different strings because dict key order in the JSON output depends on insertion order.

Additionally, `[1, 2]` and `(1, 2)` both serialize to `[1, 2]` in JSON, causing collisions.

The fix requires:
1. Sort kwargs keys for deterministic order
2. Distinguish lists from tuples in the serialization
3. Recursively normalize nested structures

```python
import json


def _normalize(value):
    """Recursively normalize a value for stable serialization.

    - dicts: sort by key
    - lists: wrap in ["list", [...]]
    - tuples: wrap in ["tuple", [...]]
    - primitives: pass through
    """
    if isinstance(value, dict):
        return ["dict", [[k, _normalize(v)] for k, v in sorted(value.items())]]
    elif isinstance(value, list):
        return ["list", [_normalize(item) for item in value]]
    elif isinstance(value, tuple):
        return ["tuple", [_normalize(item) for item in value]]
    elif value is None or isinstance(value, (bool, int, float, str)):
        return value
    else:
        raise TypeError(f"Unsupported type: {type(value).__name__}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""
    # Validate dict keys are strings
    for kwarg in kwargs.values():
        _validate_keys(kwargs)
    for arg in args:
        _validate_keys_recursive(arg)

    normalized_args = tuple(_normalize(arg) for arg in args)
    normalized_kwargs = {k: _normalize(v) for k, v in sorted(kwargs.items())}

    return json.dumps([normalized_args, normalized_kwargs], sort_keys=True)


def _validate_keys(d):
    """Validate that all dict keys are strings."""
    if isinstance(d, dict):
        for k, v in d.items():
            if not isinstance(k, str):
                raise TypeError(f"Dict keys must be strings, got {type(k).__name__}")
            _validate_keys(v)
    elif isinstance(d, (list, tuple)):
        for item in d:
            _validate_keys(item)


def _validate_keys_recursive(value):
    """Recursively validate dict keys in a value."""
    if isinstance(value, dict):
        for k, v in value.items():
            if not isinstance(k, str):
                raise TypeError(f"Dict keys must be strings, got {type(k).__name__}")
            _validate_keys_recursive(v)
    elif isinstance(value, (list, tuple)):
        for item in value:
            _validate_keys_recursive(item)
```

