import json


def _normalize_for_key(obj):
    """Recursively normalize an object to a canonical form for key generation.

    - Lists and tuples are both converted to lists with normalized elements
    - Dicts have their keys sorted alphabetically
    - All other values are returned as-is

    This ensures that [1, 2] and (1, 2) produce different representations,
    and dict key order doesn't matter.
    """
    if obj is None or isinstance(obj, bool):
        # bool must be checked before int because bool is a subclass of int
        return ('__type__', 'bool', obj)
    elif isinstance(obj, int):
        return ('__type__', 'int', obj)
    elif isinstance(obj, float):
        return ('__type__', 'float', obj)
    elif isinstance(obj, str):
        return ('__type__', 'str', obj)
    elif isinstance(obj, list):
        return ('__type__', 'list', [_normalize_for_key(item) for item in obj])
    elif isinstance(obj, tuple):
        return ('__type__', 'tuple', [_normalize_for_key(item) for item in obj])
    elif isinstance(obj, dict):
        # Validate all keys are strings
        for key in obj.keys():
            if not isinstance(key, str):
                raise TypeError(f"Dict keys must be strings, got {type(key).__name__}")
        # Sort by key and normalize values
        sorted_items = sorted(obj.items(), key=lambda x: x[0])
        return ('__type__', 'dict', [(k, _normalize_for_key(v)) for k, v in sorted_items])
    else:
        raise TypeError(f"Unsupported type: {type(obj).__name__}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""
    normalized_args = tuple(_normalize_for_key(arg) for arg in args)
    normalized_kwargs = {k: _normalize_for_key(v) for k, v in kwargs.items()}
    return json.dumps([normalized_args, normalized_kwargs], sort_keys=True)
