```python
def parse_int(text, default=None):
    """Parse a human-entered integer. Accepts surrounding whitespace, an optional leading + or -, and ASCII digits, optionally with thousands commas in correct groups of three ('1,234', '-12,345,678'). Returns `default` for anything else: empty text, '1,23', '1,,234', ',5', '12.5', '1e3', '1_000', non-ASCII digits, a bare sign, or a non-string argument."""
    if not isinstance(text, str):
        return default

    s = text.strip()
    if not s:
        return default

    # Handle optional leading sign
    sign = 1
    if s[0] == '+':
        s = s[1:]
    elif s[0] == '-':
        sign = -1
        s = s[1:]

    if not s:
        return default

    # Split by commas
    parts = s.split(',')

    # Validate comma grouping:
    # - If there's only one part, it must be all digits.
    # - If there are multiple parts:
    #   - All parts except the first must be exactly 3 digits.
    #   - The first part must be 1-3 digits.
    #   - No empty parts (handles leading/trailing/double commas).

    if len(parts) == 1:
        core = parts[0]
        if not core:
            return default
        if not core.isdigit():
            return default
        # Ensure ASCII digits only (isdigit() can return True for some Unicode digits)
        if not all('0' <= c <= '9' for c in core):
            return default
    else:
        # Check first part: must be 1 to 3 digits
        first = parts[0]
        if not first or len(first) > 3:
            return default
        if not all('0' <= c <= '9' for c in first):
            return default

        # Check remaining parts: each must be exactly 3 digits
        for part in parts[1:]:
            if len(part) != 3:
                return default
            if not all('0' <= c <= '9' for c in part):
                return default

        core = ''.join(parts)

    # Final validation: ensure core is not empty and consists only of ASCII digits
    if not core:
        return default

    try:
        value = int(core)
        return sign * value
    except ValueError:
        return default
