The bug is that `get()` does not update the usage order, so a recently-read key can be evicted incorrectly. The fix is to track access order explicitly and move a key to the "most recently used" position on both `get()` and `put()`.

```python
class LRUCache:
    """Least-recently-used cache. get() and put() both count as use. When put() would exceed capacity, evict the least recently used key. get() of a missing key returns None. capacity < 1 raises ValueError."""

    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.data = {}
        self._order = []  # list of keys, least-recently-used at index 0

    def _touch(self, key):
        # Move key to the end (most recently used)
        self._order.remove(key)
        self._order.append(key)

    def get(self, key):
        if key not in self.data:
            return None
        self._touch(key)
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self.data[key] = value
            self._touch(key)
        else:
            if len(self.data) >= self.capacity:
                # Evict least recently used
                lru_key = self._order.pop(0)
                del self.data[lru_key]
            self.data[key] = value
            self._order.append(key)
