def compare_versions(a, b):
    """Compare dotted numeric versions: -1 if a < b, 0 if equal, 1 if a > b. Compare each part as a number ('1.10' > '1.9', '01.2' == '1.2'). Missing trailing parts count as 0 ('1.0' == '1.0.0'). Empty or non-numeric parts raise ValueError."""
    def parse_version(v):
        if not v:
            raise ValueError("Empty version string")
        parts = v.split('.')
        if any(p == "" for p in parts):
            raise ValueError("Empty part in version string")
        try:
            return [int(p) for p in parts]
        except ValueError:
            raise ValueError("Non-numeric part in version string")

    a_parts = parse_version(a)
    b_parts = parse_version(b)

    # Normalize lengths by padding with zeros
    max_len = max(len(a_parts), len(b_parts))
    a_parts.extend([0] * (max_len - len(a_parts)))
    b_parts.extend([0] * (max_len - len(b_parts)))

    if a_parts < b_parts:
        return -1
    elif a_parts > b_parts:
        return 1
    else:
        return 0
```

The bug is that the current implementation performs a lexicographic string comparison instead of a numeric comparison of version components. For example, `"1.10" < "1.9"` lexicographically because `"1"` == `"1"`, then `"."` == `"."`, then `"1"` < `"9"`.

The fix splits both version strings by `.`, converts each part to an integer, pads the shorter list with zeros, and compares the resulting integer lists.

```python
def compare_versions(a, b):
    """Compare dotted numeric versions: -1 if a < b, 0 if equal, 1 if a > b. Compare each part as a number ('1.10' > '1.9', '01.2' == '1.2'). Missing trailing parts count as 0 ('1.0' == '1.0.0'). Empty or non-numeric parts raise ValueError."""
    if not a or not b:
        raise ValueError("Version strings must not be empty")

    parts_a = a.split('.')
    parts_b = b.split('.')

    if not parts_a or not parts_b:
        raise ValueError("Version strings must not be empty")

    ints_a = []
    ints_b = []

    for p in parts_a:
        if not p:
            raise ValueError("Empty version part")
        try:
            ints_a.append(int(p))
        except ValueError:
            raise ValueError(f"Non-numeric version part: {p}")

    for p in parts_b:
        if not p:
            raise ValueError("Empty version part")
        try:
            ints_b.append(int(p))
        except ValueError:
            raise ValueError(f"Non-numeric version part: {p}")

    # Pad the shorter list with zeros
    max_len = max(len(ints_a), len(ints_b))
    ints_a += [0] * (max_len - len(ints_a))
    ints_b += [0] * (max_len - len(ints_b))

    if ints_a < ints_b:
        return -1
    elif ints_a > ints_b:
        return 1
    else:
        return 0
