        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def eat():
        nonlocal pos
        pos += 1
        return tokens[pos - 1]

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        if t == "(":
            eat()  # consume '('
            v = add()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            eat()  # consume ')'
            return v
        if t == "-":
            eat()  # consume '-'
            return -atom()
        if t == "+":
            eat()  # consume '+'
            return atom()
        if t in ("*", "/", ")"):
            raise ValueError("Dangling operator or unexpected token")
        # Must be a number
        eat()
        return int(t)

    def mul():
        v = atom()
        while peek() in ("*", "/"):
            op = eat()
            right = atom()
            if op == "*":
                v = v * right
            else:
