import json
from typing import Any, Dict, List, Tuple, Union


def _normalize_value(value: Any) -> Any:
    """
    Recursively normalize a value into a JSON-serializable structure that
    preserves Python type distinctions between list and tuple, and validates
    allowed types.

    Allowed: None, bool, int, float, str, list, tuple, dict (with str keys).
    Raises TypeError for anything else.
    """
    # Order matters: bool is a subclass of int in Python
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return value
    if isinstance(value, str):
        return value

    if isinstance(value, list):
        return ["list", [_normalize_value(item) for item in value]]

    if isinstance(value, tuple):
        return ["tuple", [_normalize_value(item) for item in value]]

    if isinstance(value, dict):
        normalized_dict = {}
        for k, v in value.items():
            if not isinstance(k, str):
                raise TypeError(f"Dictionary keys must be strings, got {type(k).__name__}")
            normalized_dict[k] = _normalize_value(v)
        return normalized_dict

    raise TypeError(f"Unsupported argument type: {type(value).__name__}")


