import re

def parse_int(text, default=None):
    """Parse a human-entered integer. Accepts surrounding whitespace, an optional leading + or -, and ASCII digits, optionally with thousands commas in correct groups of three ('1,234', '-12,345,678'). Returns `default` for anything else: empty text, '1,23', '1,,234', ',5', '12.5', '1e3', '1_000', non-ASCII digits, a bare sign, or a non-string argument."""
    if not isinstance(text, str):
        return default

    s = text.strip()
    if not s:
        return default

    # Pattern: optional sign, then either a single digit or digits with correct comma grouping
    # Correct grouping: optional initial 1-3 digits, then zero or more groups of , followed by exactly 3 digits
    pattern = r'^[+-]?(\d{1,3}(,\d{3})*|\d+)$'
    if not re.match(pattern, s):
        return default

    # Ensure no double commas, leading/trailing commas, or underscores
    if ',' in s:
        parts = s.lstrip('+-').split(',')
        # First part can be 1-3 digits, rest must be exactly 3 digits
        if len(parts[0]) == 0 or len(parts[0]) > 3:
            return default
        for part in parts[1:]:
            if len(part) != 3:
                return default
        # Check for empty parts (e.g., '1,,234' or ',5' or '5,')
        if any(len(part) == 0 for part in parts):
            return default

    # Remove commas and convert to int
    try:
        return int(s.replace(',', ''))
    except ValueError:
        return default
