```python
def parse_int(text, default=None):
    """Parse a human-entered integer. Accepts surrounding whitespace, an optional leading + or -, and ASCII digits, optionally with thousands commas in correct groups of three ('1,234', '-12,345,678'). Returns `default` for anything else: empty text, '1,23', '1,,234', ',5', '12.5', '1e3', '1_000', non-ASCII digits, a bare sign, or a non-string argument."""
    if not isinstance(text, str):
        return default

    # Strip surrounding whitespace
    s = text.strip()

    if not s:
        return default

    # Handle optional leading sign
    sign = 1
    if s[0] == '+':
        s = s[1:]
    elif s[0] == '-':
        sign = -1
        s = s[1:]

    # After removing sign, check if empty (bare sign case)
    if not s:
        return default

    # Split by comma to validate grouping
    parts = s.split(',')

    # Validate comma grouping:
    # 1. No empty parts (catches leading/trailing commas or double commas like '1,,2')
    if any(part == '' for part in parts):
        return default

    # 2. All parts except possibly the first must be exactly 3 digits
    # The first part (leftmost) can be 1 to 3 digits, but not 0 digits (already checked above)
    # However, if there are multiple parts, the first part must be 1-3 digits.
    # If there is only one part, it can be any length >= 1.

    if len(parts) > 1:
        # Check all parts after the first are exactly 3 digits
        for part in parts[1:]:
            if len(part) != 3 or not part.isdigit():
                return default

        # Check the first part is 1-3 digits
        if len(parts[0]) < 1 or len(parts[0]) > 3 or not parts[0].isdigit():
            return default
    else:
        # Only one part, must be all digits
        if not parts[0].isdigit():
            return default

    # Reconstruct the digit string without commas
    digits = ''.join(parts)

    # Convert to int and apply sign
    try:
        value = int(digits)
        return sign * value
    except ValueError:
        return default
