def running_balance(opening, transactions):
    """Apply transactions in order. Each is a dict {"type": "credit" or "debit", "amount": positive int cents}. Returns (closing_balance, balances_after_each_transaction). Balance may go negative on a debit. Raises ValueError for an unknown type, an amount that is not a positive int, or if the input transaction dict already contains a 'balance' key. Does not modify the input transactions."""
    balances = []
    bal = opening

    # Validate all transactions before applying any changes
    for t in transactions:
        # Check for unknown types
        if t["type"] not in ("credit", "debit"):
            raise ValueError(f"Unknown transaction type: {t['type']}")

        # Check amount is a positive integer
        amount = t["amount"]
        if not isinstance(amount, int) or amount <= 0:
            raise ValueError(f"Amount must be a positive integer, got: {amount}")

    # Apply transactions without modifying the original dicts
    for t in transactions:
        if t["type"] == "credit":
            bal += t["amount"]
        else:  # type == "debit" (already validated)
            bal -= t["amount"]
        balances.append(bal)

