import json
from typing import Any, Dict, List, Tuple, Union


def _normalize_value(value: Any) -> Any:
    """
    Recursively normalize a value into a canonical form suitable for stable hashing.

    Rules:
    - dict: sort by keys (keys must be strings)
    - list/tuple: convert to list and normalize elements (preserves order within the sequence)
    - Primitive types (None, bool, int, float, str): return as-is
    - Distinguish between list and tuple by wrapping in a tagged structure
    """
    if value is None:
        return None
    if isinstance(value, bool):
        # Must check bool before int since bool is a subclass of int
        return ("__type__", "bool", value)
    if isinstance(value, int):
        return ("__type__", "int", value)
    if isinstance(value, float):
        return ("__type__", "float", value)
    if isinstance(value, str):
        return ("__type__", "str", value)
    if isinstance(value, dict):
        # Validate all keys are strings
        for k in value.keys():
            if not isinstance(k, str):
                raise TypeError(f"Dict keys must be strings, got {type(k).__name__}")
        # Sort by keys and normalize values
        sorted_items = sorted(value.items(), key=lambda x: x[0])
        return [("__type__", "dict", [(k, _normalize_value(v)) for k, v in sorted_items])]
    if isinstance(value, list):
        return [("__type__", "list", [_normalize_value(item) for item in value])]
    if isinstance(value, tuple):
        return [("__type__", "tuple", [_normalize_value(item) for item in value])]

    raise TypeError(f"Unsupported type: {type(value).__name__}")


def cache_key(*args, **kwargs) -> str:
    """
    Stable string key for a call. Equal calls give equal keys: keyword order and 
    nested dict key order do not matter. Values that differ in type give different 
    keys: 1, 1.0 and True are all different, and a list differs from a tuple with 
    the same items. Positional and keyword arguments are distinct 
    (cache_key(1) != cache_key(x=1)). 

    Allowed values: None, bool, int, float, str, and lists, tuples and dicts 
    (with str keys) of those. Anything else, including dicts with non-str keys, 
    raises TypeError.
    """
    # Normalize positional arguments
    normalized_args = tuple(_normalize_value(arg) for arg in args)

    # Normalize keyword arguments (sorted by key name for stability)
    sorted_kwargs = sorted(kwargs.items(), key=lambda x: x[0])
    normalized_kwargs = [(k, _normalize_value(v)) for k, v in sorted_kwargs]

    # Create a structure that distinguishes args from kwargs and preserves types
    # The structure ensures cache_key(1, 2) != cache_key(a=1, b=2)
    canonical = {
        "args": normalized_args,
        "kwargs": normalized_kwargs
    }

    return json.dumps(canonical, separators=(',', ':'))
