def parse_int(text, default=None):
    """Parse a human-entered integer. Accepts surrounding whitespace, an optional leading + or -, and ASCII digits, optionally with thousands commas in correct groups of three ('1,234', '-12,345,678'). Returns `default` for anything else: empty text, '1,23', '1,,234', ',5', '12.5', '1e3', '1_000', non-ASCII digits, a bare sign, or a non-string argument."""
    if not isinstance(text, str):
        return default

    s = text.strip()
    if not s:
        return default

    # Handle optional leading sign
    sign = 1
    if s[0] == '+':
        s = s[1:]
    elif s[0] == '-':
        sign = -1
        s = s[1:]

    if not s:
        return default

    # Split by commas and validate structure
    parts = s.split(',')

    # Validate comma grouping:
    # - If there's more than one part, all but the last must be exactly 3 digits
    # - The last part must be 1-3 digits (or exactly 3 if there are multiple parts? No, last can be 1-3)
    # - No empty parts allowed (catches leading/trailing/double commas)

    if len(parts) == 1:
        # No commas: must be all ASCII digits
        if not parts[0].isdigit() or not all(c in '0123456789' for c in parts[0]):
            return default
        if not parts[0]:  # empty string after split
            return default
    else:
        # Multiple parts: validate each
        # All parts must be non-empty
        if any(len(p) == 0 for p in parts):
            return default

        # All parts must be ASCII digits only
        for p in parts:
            if not all(c in '0123456789' for c in p):
                return default

        # All but last must be exactly 3 digits
        for p in parts[:-1]:
            if len(p) != 3:
                return default

        # Last part must be 1-3 digits
        if len(parts[-1]) < 1 or len(parts[-1]) > 3:
            return default

    # Reconstruct digit string and convert
    digit_str = ''.join(parts)

    # Final check: ensure all characters are ASCII digits (redundant but safe)
    if not digit_str or not all(c in '0123456789' for c in digit_str):
        return default

    return sign * int(digit_str)
