from typing import Any, Dict, List, Tuple, Union

# Allowed types for cache key values
AllowedValue = Union[
    None,
    bool,
    int,
    float,
    str,
    List['AllowedValue'],
    Tuple['AllowedValue', ...],
    Dict[str, 'AllowedValue']
]


def _normalize_value(value: Any) -> Any:
    """
    Recursively normalize a value to ensure stable serialization.
    - Lists are converted to tuples (so [1, 2] != (1, 2) but both are hashable/consistent internally).
    - Dicts are sorted by key to ensure order independence.
    - Type distinctions are preserved (bool vs int, list vs tuple).
