        return None
    if isinstance(value, bool):
        # Must check bool before int because bool is a subclass of int
        return ('__type__', 'bool', value)
    if isinstance(value, int):
        return ('__type__', 'int', value)
    if isinstance(value, float):
        return ('__type__', 'float', value)
    if isinstance(value, str):
        return ('__type__', 'str', value)
    if isinstance(value, list):
        return ('__type__', 'list', tuple(_normalize_value(item) for item in value))
    if isinstance(value, tuple):
        return ('__type__', 'tuple', tuple(_normalize_value(item) for item in value))
    if isinstance(value, dict):
        # Validate keys are strings
        for k in value.keys():
            if not isinstance(k, str):
                raise TypeError(f"Dict keys must be strings, got {type(k).__name__}")
        # Sort by key and normalize values
        sorted_items = sorted(value.items(), key=lambda x: x[0])
        normalized_items = [(k, _normalize_value(v)) for k, v in sorted_items]
        return ('__type__', 'dict', tuple(normalized_items))

    raise TypeError(f"Unsupported type for cache_key: {type(value).__name__}")


