    """
    Stable string key for a call. Equal calls give equal keys: keyword order and 
    nested dict key order do not matter. Values that differ in type give different 
    keys: 1, 1.0 and True are all different, and a list differs from a tuple with 
    the same items. Positional and keyword arguments are distinct 
    (cache_key(1) != cache_key(x=1)). 

    Allowed values: None, bool, int, float, str, and lists, tuples and dicts 
    (with str keys) of those. Anything else, including dicts with non-str keys, 
    raises TypeError.
    """
    # Normalize positional arguments
    normalized_args = tuple(_normalize_value(arg) for arg in args)

    # Normalize keyword arguments (sorted by key to ensure order independence)
    sorted_kwargs_keys = sorted(kwargs.keys())
    normalized_kwargs = tuple((k, _normalize_value(kwargs[k])) for k in sorted_kwargs_keys)

    # Create a structure that distinguishes args from kwargs and preserves types
