import json


def _normalize_value(value):
    """Recursively normalize a value into a hashable, type-distinct structure.

    - Preserves type distinction between bool, int, float, str, list, tuple, dict.
    - Sorts dict keys for stable ordering.
    - Converts lists to tuples (with a marker) to distinguish from native tuples.
    - Ensures None, bool, int, float, str are kept as-is but type-separated.
    """
    # Check bool before int because bool is a subclass of int
    if isinstance(value, bool):
        return ('__bool__', value)
    if value is None:
        return ('__none__', None)
    if isinstance(value, int):
        return ('__int__', value)
    if isinstance(value, float):
        return ('__float__', value)
    if isinstance(value, str):
        return ('__str__', value)
    if isinstance(value, list):
        return ('__list__', tuple(_normalize_value(item) for item in value))
    if isinstance(value, tuple):
        return ('__tuple__', tuple(_normalize_value(item) for item in value))
    if isinstance(value, dict):
        # Validate all keys are strings
        for k in value.keys():
            if not isinstance(k, str):
                raise TypeError(f"Dict keys must be strings, got {type(k).__name__}")
        # Sort by key for stable ordering
        sorted_items = sorted(value.items(), key=lambda x: x[0])
        return ('__dict__', tuple((k, _normalize_value(v)) for k, v in sorted_items))

    raise TypeError(f"Unsupported type: {type(value).__name__}")


def cache_key(*args, **kwargs):
    """Stable string key for a call. Equal calls give equal keys: keyword order and nested dict key order do not matter. Values that differ in type give different keys: 1, 1.0 and True are all different, and a list differs from a tuple with the same items. Positional and keyword arguments are distinct (cache_key(1) != cache_key(x=1)). Allowed values: None, bool, int, float, str, and lists, tuples and dicts (with str keys) of those. Anything else, including dicts with non-str keys, raises TypeError."""
    normalized_args = tuple(_normalize_value(arg) for arg in args)
    normalized_kwargs = {k: _normalize_value(v) for k, v in kwargs.items()}

    # Create a structure that separates args and kwargs clearly
    # Sort kwargs keys to ensure stable ordering regardless of input order
    sorted_kwargs = tuple(sorted(normalized_kwargs.items(), key=lambda x: x[0]))

    return json.dumps(('__call__', normalized_args, sorted_kwargs), sort_keys=False)
```

```python
def parse_int(text, default=None):
    """Parse a human-entered integer. Accepts surrounding whitespace, an optional leading + or -, and ASCII digits, optionally with thousands commas in correct groups of three ('1,234', '-12,345,678'). Returns `default` for anything else: empty text, '1,23', '1,,234', ',5', '12.5', '1e3', '1_000', non-ASCII digits, a bare sign, or a non-string argument."""
    if not isinstance(text, str):
        return default

    s = text.strip()
    if not s:
        return default

    # Handle optional leading sign
    sign = 1
    if s[0] == '+':
        s = s[1:]
    elif s[0] == '-':
        sign = -1
        s = s[1:]

    if not s:
        return default

    # Split by commas and validate structure
    parts = s.split(',')

    # Validate comma grouping:
    # - If there's only one part, it must be all digits (no commas used)
    # - If there are multiple parts:
    #   - All parts except the first must be exactly 3 digits
    #   - The first part must be 1-3 digits (no leading zeros unless it's just "0")
    if len(parts) == 1:
        digit_part = parts[0]
    else:
        # Check all trailing parts are exactly 3 digits
        for part in parts[1:]:
            if len(part) != 3 or not part.isdigit():
                return default
        digit_part = parts[0]
        # First part must be 1-3 digits
        if not (1 <= len(digit_part) <= 3) or not digit_part.isdigit():
            return default
        # No leading zeros in first part unless it's exactly "0"
        if len(digit_part) > 1 and digit_part[0] == '0':
            return default

    # Ensure all characters are ASCII digits
    if not digit_part.isdigit():
        return default

    # Check for non-ASCII digits (isdigit() returns True for some Unicode digits)
    # We need to ensure only ASCII digits 0-9
    if not all(c in '0123456789' for c in digit_part):
        return default

    try:
        return sign * int(digit_part)
    except ValueError:
        return default
