class Bus:
    def __init__(self):
        self.subs = {}
        self._subscribing = {}
        self._unsubscribing = {}

    def on(self, topic, handler, priority=0):
        if topic not in self.subs:
            self.subs[topic] = []

        # Use a unique wrapper to allow same function multiple times
        entry = {'priority': priority, 'handler': handler, 'active': True}
        self.subs[topic].append(entry)

        # Sort: higher priority first, then by subscription order (stable sort preserves insertion order for equal keys)
        # We negate priority so higher numbers come first
        self.subs[topic].sort(key=lambda x: -x['priority'])

        def unsubscribe():
            if topic in self.subs:
                for e in self.subs[topic]:
                    if e is entry and e['active']:
                        e['active'] = False
                        # If we are currently emitting, mark for removal after emit
                        if topic in self._unsubscribing:
                            self._unsubscribing[topic].append(e)
                        break
            # Calling twice is harmless - just do nothing if already inactive

        return unsubscribe

    def emit(self, topic, *args):
        if topic not in self.subs:
            return 0

        # Initialize tracking for this emit cycle
        self._unsubscribing[topic] = []
        self._subscribing[topic] = []

        n = 0
        # Create a snapshot of active handlers for this emit
        handlers_to_call = []
        for entry in self.subs[topic]:
            if entry['active']:
                handlers_to_call.append(entry['handler'])

        # Call handlers
        for handler in handlers_to_call:
            # Check if this handler was unsubscribed by an earlier handler in this same emit
            # We need to check if the specific subscription entry is still active
            still_active = False
            for entry in self.subs[topic]:
                if entry['handler'] is handler and entry['active']:
