class Bus:
    def __init__(self):
        self.subs = {}
        self._emit_locks = {}

    def on(self, topic, handler, priority=0):
        if topic not in self.subs:
            self.subs[topic] = []

        # Create a unique subscription entry
        entry = [priority, handler, True]  # [priority, handler, is_active]
        self.subs[topic].append(entry)

        # Sort: higher priority first, stable sort preserves insertion order for equal priorities
        self.subs[topic].sort(key=lambda x: -x[0])

        def unsubscribe():
            if not entry[2]:  # Already inactive
                return
            entry[2] = False
            # If we're in the middle of an emit for this topic, clean up after
            if topic in self._emit_locks:
                # Mark for cleanup after emit completes
                pass
            else:
                # Clean up immediately if not emitting
                if topic in self.subs:
                    self.subs[topic] = [e for e in self.subs[topic] if e[2]]

        return unsubscribe

    def emit(self, topic, *args):
        if topic not in self.subs:
            return 0

        # Mark that we're emitting this topic
        self._emit_locks[topic] = True

        # Get snapshot of currently active handlers in correct order
        active_entries = [e for e in self.subs[topic] if e[2]]

        n = 0
        for entry in active_entries:
            if entry[2]:  # Check again in case it was unsubscribed by earlier handler
                entry[1](*args)
                n += 1

        # Clean up inactive entries after emit
        self.subs[topic] = [e for e in self.subs[topic] if e[2]]

        # Remove emit lock
        del self._emit_locks[topic]

        return n
