def wrap(text, width):
    if width < 1:
        raise ValueError("width must be >= 1")

    if not text or not text.strip():
        return []

    # Split into paragraphs (separated by one or more blank lines)
    paragraphs = []
    current_para = []
    lines = text.split('\n')

    for line in lines:
        if line.strip() == '':
            if current_para:
                paragraphs.append(' '.join(current_para))
                current_para = []
            # else: multiple blank lines, just continue
        else:
            # Split line into words and add to current paragraph
            words = line.split()
            current_para.extend(words)

    # Don't forget the last paragraph
    if current_para:
        paragraphs.append(' '.join(current_para))

    result = []

    for para in paragraphs:
        words = para.split()
        line = ""

        for w in words:
            if not w:
                continue

            # If word is longer than width, cut it into pieces
            while len(w) > width:
                # If there's content in current line, flush it first
                if line:
                    result.append(line)
                    line = ""
                # Add a piece of the word
                result.append(w[:width])
                w = w[width:]

            # Now w fits in width (or is empty)
            if not w:
                continue

            if line == "":
                line = w
            elif len(line) + 1 + len(w) <= width:
                line = line + " " + w
            else:
                result.append(line)
                line = w

        if line:
            result.append(line)

        # Add blank line between paragraphs (but not after the last one)
        result.append("")

    # Remove the trailing empty string if present
    if result and result[-1] == "":
        result.pop()

    return result
