def load_config(defaults, env, prefix="APP_"):
    """
    Build a new config dict from defaults, overridden by environment variables.

    Rules:
    - Only env keys starting with `prefix` are considered.
    - The part after the prefix is lowercased, then split on "__" (double underscore)
      to form the nesting path. A single underscore is part of the key name.
    - The leaf value is cast to the type of the existing default value.
    - bool: accepts 1/true/yes/on and 0/false/no/off (case-insensitive); else ValueError.
    - int/float: parsed numerically; else ValueError.
    - Other types: remain as the raw string.
    - Env keys without the prefix, or paths that do not exist in defaults, are ignored.
    - The defaults object is never modified.
    """

    def _convert(value, target_type):
        if target_type is bool:
            v = value.strip().lower()
            if v in ("1", "true", "yes", "on"):
                return True
            if v in ("0", "false", "no", "off"):
                return False
            raise ValueError(f"Invalid boolean value: {value!r}")
        if target_type is int:
            return int(value)
        if target_type is float:
            return float(value)
        # For any other type, keep as string
        return value

    def _deep_copy(obj):
        if isinstance(obj, dict):
            return {k: _deep_copy(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_deep_copy(item) for item in obj]
        return obj

    cfg = _deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Extract path: remove prefix, lowercase, split on "__"
        path_str = k[len(prefix):].lower()
        path = path_str.split("__")

        # Traverse to the parent node
        node = cfg
        valid = True
        for p in path[:-1]:
            if not isinstance(node, dict) or p not in node:
                valid = False
                break
            node = node[p]

        if not valid:
            continue

        leaf_key = path[-1]
        if not isinstance(node, dict) or leaf_key not in node:
            continue

        target_type = type(node[leaf_key])
        try:
            node[leaf_key] = _convert(raw, target_type)
        except (ValueError, TypeError):
            # Ignore variables that cannot be converted to the expected type
            continue

    return cfg
