def load_config(defaults, env, prefix="APP_"):
    """
    Load configuration from environment variables, overriding defaults.

    - Variables named PREFIX + PATH override the value at that path.
    - PATH is lower-cased; double underscores separate nesting levels.
    - Single underscores are part of the key name.
    - Raw strings are converted to the type of the default value.
    - Bool accepts: 1/true/yes/on (True) or 0/false/no/off (False), case-insensitive.
    - Unknown paths or variables without prefix are ignored.
    - Defaults object is not modified.
    """
    import copy

    # Deep copy to avoid modifying defaults
    cfg = copy.deepcopy(defaults)

    def parse_bool(value):
        """Parse boolean from string."""
        val = value.strip().lower()
        if val in ('1', 'true', 'yes', 'on'):
            return True
        elif val in ('0', 'false', 'no', 'off'):
            return False
        else:
            raise ValueError(f"Invalid boolean value: {value}")

    def convert_value(target_type, raw):
        """Convert raw string to target type."""
        if target_type is bool:
            return parse_bool(raw)
        elif target_type is int:
            return int(raw)
        elif target_type is float:
            return float(raw)
        else:
            # For str and any other type, just return as string
            return target_type(raw)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Extract path part after prefix
        path_part = k[len(prefix):]

        # Split by double underscore for nesting, single underscore is part of key
        path = path_part.lower().split("__")

        # Navigate to the parent node
        node = cfg
        valid_path = True

        for p in path[:-1]:
            if p not in node:
                valid_path = False
                break
            node = node[p]

        if not valid_path:
            continue

        # Check if final key exists
        final_key = path[-1]
        if final_key not in node:
            continue

        # Get the target type from the default value
        target_type = type(node[final_key])

        try:
            converted_value = convert_value(target_type, raw)
            node[final_key] = converted_value
        except (ValueError, TypeError):
            # Skip invalid conversions rather than crashing
            continue

    return cfg
