import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parens. Reject unknown chars.
    raw = s.replace(" ", "")
    if not raw:
        raise ValueError("Empty expression")

    # Check for invalid characters before tokenizing
    if re.search(r"[^\d.\-+*/^()]", raw):
        raise ValueError("Invalid character in expression")

    toks = re.findall(r"\d+\.?\d*|\.\d+|[-+*/^()]", raw)
    if not toks:
        raise ValueError("No valid tokens")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        pos += 1
        return t

    def expect(token):
        t = take()
        if t != token:
            raise ValueError(f"Expected '{token}', got '{t}'")
        return t

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = unary()
        while peek() in ("*", "/"):
            op = take()
            r = unary()
            if op == "/" and r == 0:
                raise ZeroDivisionError("Division by zero")
            v = v * r if op == "*" else v / r
        return v

    def unary():
        if peek() == "+":
            take()
            return unary()
        if peek() == "-":
            take()
            return -unary()
        return power()

    def power():
        v = atom()
        while peek() == "^":
            take()
            # Right-associative: exponent is unary (allows -2^2 = -(2^2))
            exp = unary()
            v = v ** exp
        return v

    def atom():
        t = peek()
        if t == "(":
            take()
            v = expr()
            expect(")")
            return v
        if t in ("+", "-", "*", "/", "^", ")"):
            raise ValueError(f"Unexpected token '{t}'")
        if t is None:
            raise ValueError("Unexpected end of expression")
        take()
        return float(t)

    result = expr()
    if pos != len(toks):
        raise ValueError("Unexpected trailing content")
    return result
