I'll analyze the bugs and fix them systematically using test-driven development.

## Bug Analysis

1. **`-2^2` gives 4 instead of -4**: The unary minus is being applied inside `atom()`, but exponentiation has higher precedence than unary minus. So `-2^2` should be parsed as `-(2^2)` = -4, not `(-2)^2` = 4.

2. **`2^3^2` gives 64 instead of 512**: Exponentiation should be right-associative (`2^(3^2)` = 2^9 = 512), but the current `power()` function is left-associative (`(2^3)^2` = 8^2 = 64).

3. **Garbage like `"2 $ 3"` or `"(2"` is silently accepted**: The tokenizer doesn't validate input, and there's no check for unconsumed tokens or invalid characters.

4. **Missing validation**: No check for empty input, two numbers in a row, missing operands, unbalanced parentheses, or division by zero.

Let me write the corrected module:

```python
import re


def evaluate(s):
    if not s or not s.strip():
        raise ValueError("Empty expression")

    # Tokenize: numbers (including decimals), operators, parentheses, and capture whitespace
    # We need to detect invalid characters
    token_pattern = r"\d+\.?\d*|\.\d+|[-+*/^()]|\s+|[^\d\s.+*/^()\-]"
    raw_tokens = re.findall(token_pattern, s)

    # Filter out whitespace and check for invalid tokens
    toks = []
    for t in raw_tokens:
        if t.strip() == "":
            continue
        if re.match(r"[^\d\s.+*/^()\-]", t):
            raise ValueError(f"Invalid character in expression")
        toks.append(t)

    if not toks:
        raise ValueError("Empty expression")

    pos = 0
    prev_was_operand = False  # Track if previous token was an operand

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        pos += 1
        return t

    def expect_operand():
        nonlocal prev_was_operand
        if prev_was_operand:
            raise ValueError("Two operands in a row")
        prev_was_operand = True

    def expect_operator():
        nonlocal prev_was_operand
        if not prev_was_operand:
            raise ValueError("Missing operand")
        prev_was_operand = False

    def expr():
        v = term()
        while peek() in ("+", "-"):
            expect_operator()
            op = take()
            r = term()
            v = v + r if op == "+" else v - r
        return v

    def term():
        v = power()
        while peek() in ("*", "/"):
            expect_operator()
            op = take()
            r = power()
            if op == "/" and r == 0:
                raise ZeroDivisionError("Division by zero")
            v = v * r if op == "*" else v / r
        return v

    def power():
        # For right-associativity: parse base, then if ^, recursively parse the rest as power
        v = unary()
        if peek() == "^":
            expect_operator()
            take()  # consume '^'
            # Right-associative: the exponent itself can include unary and further powers
            exp = power()  # recursive call for right-associativity
            v = v ** exp
        return v

    def unary():
        # Handle unary + and - (higher precedence than + - but lower than ^)
        t = peek()
        if t == "-":
            take()
            return -unary()
        if t == "+":
            take()
            return unary()
        return atom()

    def atom():
        expect_operand()
        t = take()
        if t is None:
            raise ValueError("Missing operand")
        if t == "(":
            v = expr()
            if peek() != ")":
                raise ValueError("Unbalanced parentheses")
            take()  # consume ')'
            return v
        if t == ")":
            raise ValueError("Unbalanced parentheses")
        if t in ("+", "-", "*", "/", "^"):
            raise ValueError("Missing operand")
        # Must be a number
        try:
            return float(t)
        except ValueError:
            raise ValueError(f"Invalid token: {t}")

    result = expr()

    # Check that all tokens were consumed
    if peek() is not None:
        raise ValueError("Unexpected token at end of expression")

    # Check for unbalanced parentheses (unclosed '(')
    # This is already handled by the parser, but let's ensure
    if prev_was_operand and peek() is None:
        pass  # OK, ended with operand

    return result
