from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, ttl):
        self.cap = capacity
        self.ttl = ttl
        self.d = OrderedDict()

    def _expire(self, key, now):
        """Return True if the entry for key is expired at time now."""
        if key not in self.d:
            return True
        _, exp = self.d[key]
        return now >= exp

    def _cleanup_expired(self, now):
        """Remove all expired entries."""
        expired_keys = [k for k in self.d if self._expire(k, now)]
        for k in expired_keys:
            del self.d[k]

    def get(self, key, now):
        if key not in self.d:
            return None
        if self._expire(key, now):
            del self.d[key]
            return None
        # Move to end to mark as most recently used
        self.d.move_to_end(key)
        return self.d[key][0]

    def put(self, key, value, now):
        if self.cap <= 0:
            return

        if key in self.d:
            # Update existing key: replace value, restart TTL, move to end (MRU)
            self.d.move_to_end(key)
            self.d[key] = (value, now + self.ttl)
            return

        # New key: first drop expired entries
        self._cleanup_expired(now)

        # If still full, evict the least recently used live entry
        if len(self.d) >= self.cap:
            self.d.popitem(last=False)

        self.d[key] = (value, now + self.ttl)

    def size(self, now):
        self._cleanup_expired(now)
        return len(self.d)
