from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, ttl):
        self.cap = capacity
        self.ttl = ttl
        self.d = OrderedDict()

    def _cleanup_expired(self, now):
        """Remove all expired entries from the cache."""
        # We must collect keys to remove first because we can't modify the dict while iterating
        expired_keys = [
            key for key, (value, exp) in self.d.items()
            if now >= exp
        ]
        for key in expired_keys:
            del self.d[key]

    def get(self, key, now):
        if key not in self.d:
            return None

        v, exp = self.d[key]

        # Check if expired (entry is expired when now >= stored_at + ttl)
        if now >= exp:
            del self.d[key]
            return None

        # Hit makes the key most recently used
        self.d.move_to_end(key)
        return v

    def put(self, key, value, now):
        # If capacity is non-positive, store nothing
        if self.cap <= 0:
            return

        # If key already exists, update it (restarts TTL, makes it MRU)
        # Updating an existing key never evicts anything
        if key in self.d:
            self.d.move_to_end(key)
            self.d[key] = (value, now + self.ttl)
            return

        # Need room for a NEW key
        if len(self.d) >= self.cap:
            # First drop every expired entry
            self._cleanup_expired(now)

            # Only if still full, evict the least recently used live entry
            if len(self.d) >= self.cap:
                self.d.popitem(last=False)

        self.d[key] = (value, now + self.ttl)

    def size(self, now):
        # Count only live entries (not expired)
        self._cleanup_expired(now)
        return len(self.d)
```

