The bug exists because `fnmatch` treats `*` as matching any character including `/` (unlike shell globbing) and does not support `**`. I will implement a custom recursive matcher that respects directory boundaries for `*` and handles `**` correctly.

```python
import re


def glob_match(pattern, path):
    """
    Match a glob pattern against a path.

    Rules:
    - '*' matches any run of characters except '/' (including none)
    - '?' matches exactly one character except '/'
    - '**' matches any characters including '/'
    - '**/' matches zero or more whole directories
    - '[abc]', '[a-c]', '[!abc]' character classes (never match '/')
    - Backslash escapes the next character
    - Everything else is literal and case-sensitive
    - Leading dot is not special
    """

    def parse_pattern(pattern):
        """Convert glob pattern to a list of tokens."""
        tokens = []
        i = 0
        n = len(pattern)

        while i < n:
            c = pattern[i]

            if c == '\\':
                # Escape sequence: next character is literal
                if i + 1 < n:
                    tokens.append(('LITERAL', pattern[i + 1]))
                    i += 2
                else:
                    tokens.append(('LITERAL', '\\'))
                    i += 1
            elif c == '*':
                if i + 1 < n and pattern[i + 1] == '*':
                    # '**'
                    tokens.append(('DOUBLE_STAR', '**'))
                    i += 2
                    # Check if followed by '/'
                    if i < n and pattern[i] == '/':
                        tokens.append(('SLASH', '/'))
                        i += 1
                else:
                    # Single '*'
                    tokens.append(('STAR', '*'))
                    i += 1
            elif c == '?':
                tokens.append(('QUESTION', '?'))
                i += 1
            elif c == '[':
                # Character class
                j = i + 1
                if j < n and pattern[j] == '!':
                    j += 1
                if j < n and pattern[j] == ']':
                    j += 1
                while j < n and pattern[j] != ']':
                    j += 1
                if j < n:
                    class_str = pattern[i:j + 1]
                    tokens.append(('CLASS', class_str))
                    i = j + 1
                else:
                    # Unclosed bracket, treat as literal
                    tokens.append(('LITERAL', '['))
                    i += 1
            elif c == '/':
                tokens.append(('SLASH', '/'))
                i += 1
            else:
                tokens.append(('LITERAL', c))
                i += 1

        return tokens

    def match_class(class_str, char):
        """Check if a character matches a character class like [abc], [a-c], [!abc]."""
        if not class_str.startswith('[') or not class_str.endswith(']'):
            return False

        inner = class_str[1:-1]
        if not inner:
            return False

        negate = False
        if inner[0] == '!':
            negate = True
            inner = inner[1:]

        # '/' never matches a character class
        if char == '/':
            return False

        matched = False
        i = 0
        while i < len(inner):
            if i + 2 < len(inner) and inner[i + 1] == '-':
                # Range
                start, end = inner[i], inner[i + 2]
                if start <= char <= end:
                    matched = True
                    break
                i += 3
            else:
                if inner[i] == char:
                    matched = True
                    break
                i += 1

        return not matched if negate else matched

    def match_tokens(tokens, t_idx, path, p_idx):
        """Recursively match tokens against the path."""
        n_tokens = len(tokens)
        n_path = len(path)

        while t_idx < n_tokens:
            token_type, token_val = tokens[t_idx]

            if token_type == 'LITERAL':
                if p_idx >= n_path or path[p_idx] != token_val:
                    return False
                p_idx += 1
                t_idx += 1
            elif token_type == 'SLASH':
                if p_idx >= n_path or path[p_idx] != '/':
                    return False
                p_idx += 1
                t_idx += 1
            elif token_type == 'QUESTION':
                if p_idx >= n_path or path[p_idx] == '/':
                    return False
                p_idx += 1
                t_idx += 1
            elif token_type == 'STAR':
                # '*' matches any sequence except '/'
                t_idx += 1
                # Try matching 0 or more non-slash characters
                for end in range(p_idx, n_path + 1):
                    # Check that we haven't crossed a '/'
                    if end > p_idx and path[end - 1] == '/':
                        break
                    if match_tokens(tokens, t_idx, path, end):
                        return True
                return False
            elif token_type == 'DOUBLE_STAR':
                # '**' matches any sequence including '/'
                t_idx += 1
                # Check if next token is SLASH (we already added it as separate token during parse)
                # Actually, we need to handle '**/' as a unit conceptually
                # But in our token stream, '**' and '/' are separate
                # So '**' alone matches everything
                for end in range(p_idx, n_path + 1):
                    if match_tokens(tokens, t_idx, path, end):
                        return True
                return False
            elif token_type == 'CLASS':
                if p_idx >= n_path:
                    return False
                if not match_class(token_val, path[p_idx]):
                    return False
                p_idx += 1
                t_idx += 1
            else:
                # Unknown token type
                t_idx += 1

        return p_idx == n_path

    tokens = parse_pattern(pattern)
    return match_tokens(tokens, 0, path, 0)
