def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    The original `obj` and everything reachable from it is left untouched.

    Rules:
    - Path is dot-separated keys with optional list indexes (e.g., "a.b[2].c").
    - Missing dict keys are created as dicts.
    - Missing list containers are created as lists.
    - Index equal to list length appends; larger index pads with None.
    - TypeError if existing value has wrong type for next step.
    - ValueError if path is empty, malformed, or starts with index.
    - First step must be a key and obj must be a dict.
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate path format before processing
    # Check for leading dot, trailing dot, double dots, or invalid index formats
    if path.startswith('.') or path.endswith('.') or '..' in path:
        raise ValueError("malformed path")

    # Parse path into steps
    # We need to handle "key[index]" or "key" or just "[index]" (but first must be key)
    steps = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current:
                steps.append(('key', current))
                current = ""
            i += 1
        elif ch == '[':
            if current:
                steps.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                j += 1
            if j >= len(path):
                raise ValueError("malformed path: unclosed bracket")
            index_str = path[i+1:j]
            if not index_str:
                raise ValueError("malformed path: empty index")
            if index_str.startswith('-') or not index_str.isdigit():
                raise ValueError("malformed path: invalid index")
            steps.append(('index', int(index_str)))
            i = j + 1
        else:
            current += ch
            i += 1

    if current:
        steps.append(('key', current))

    if not steps:
        raise ValueError("path is empty")

    if steps[0][0] != 'key':
        raise ValueError("first step must be a key")

    # Deep copy the object to ensure immutability of the original
    def deep_copy(o):
        if isinstance(o, dict):
            return {k: deep_copy(v) for k, v in o.items()}
        elif isinstance(o, list):
            return [deep_copy(item) for item in o]
        else:
            return o

    result = deep_copy(obj)

    # Navigate and build the structure
    node = result

    for idx, (step_type, step_val) in enumerate(steps[:-1]):
        next_type, next_val = steps[idx + 1]

        if step_type == 'key':
            if not isinstance(node, dict):
                raise TypeError("expected dict for key step")

            if step_val not in node:
                # Create next container based on next step
                if next_type == 'key':
                    node[step_val] = {}
                else:
                    node[step_val] = []

            node = node[step_val]

        else:  # step_type == 'index'
            if not isinstance(node, list):
                raise TypeError("expected list for index step")

            if step_val < 0 or step_val > len(node):
                # This case shouldn't happen in navigation if we built correctly,
                # but if accessing existing list with gap, we need to pad
                raise IndexError("index out of range")

            node = node[step_val]

    # Set the final value
    last_type, last_val = steps[-1]

    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError("expected dict for final key step")
        node[last_val] = value
    else:  # last_type == 'index'
        if not isinstance(node, list):
            raise TypeError("expected list for final index step")

        if last_val < 0:
            raise ValueError("negative index not allowed")

        # Pad list if necessary
        while len(node) <= last_val:
            node.append(None)

        node[last_val] = value

    return result
