class Inventory:
    def __init__(self):
        self.lots = {}

    def _cleanup(self, sku, today):
        """Remove expired lots and filter out zero-quantity lots for a given SKU."""
        if sku not in self.lots:
            return
        # Keep only lots that are not expired (expires >= today) and have quantity > 0
        self.lots[sku] = [lot for lot in self.lots[sku] if lot[0] >= today and lot[1] > 0]
        # If the list becomes empty, optionally remove the key to keep dict clean
        if not self.lots[sku]:
            del self.lots[sku]

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty, len(self.lots.get(sku, []))])
        # The third element is an insertion index to maintain FIFO for same expiry

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")

        self._cleanup(sku, today)

        if sku not in self.lots:
            raise ValueError("insufficient")

        # Sort lots: earliest expiry first, then by insertion order (FIFO)
        # lot structure: [expires, quantity, insertion_index]
        sorted_lots = sorted(self.lots[sku], key=lambda x: (x[0], x[2]))

        # Check if sufficient stock exists before modifying anything
        total_usable = sum(lot[1] for lot in sorted_lots)
        if total_usable < qty:
            raise ValueError("insufficient")

        taken = []
        remaining_qty = qty

        for lot in sorted_lots:
            if remaining_qty == 0:
                break

            n = min(remaining_qty, lot[1])
            lot[1] -= n
            remaining_qty -= n

            if n > 0:
                taken.append((lot[0], n))

        # Clean up any lots that became zero during this operation
        self._cleanup(sku, today)

        return taken

    def stock(self, sku, today):
        self._cleanup(sku, today)
        if sku not in self.lots:
            return 0
        return sum(lot[1] for lot in self.lots[sku])
