def set_path(obj, path, value):
    """
    Set a value at a nested path in a structure, returning a new structure
    without modifying the original obj or anything reachable from it.

    Args:
        obj: The original dictionary (must be a dict)
        path: Dot-separated path with optional list indexes (e.g., "a.b[2].c")
        value: The value to set at the path

    Returns:
        A new structure with the value set at the path

    Raises:
        TypeError: If path step type mismatches existing value type
        ValueError: If path is empty or malformed
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or path.startswith(".") or path.startswith("["):
        raise ValueError("Path must be non-empty and start with a key")

    # Parse the path into steps
    parts = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current == "":
                raise ValueError(f"Malformed path: empty segment at position {i}")
            parts.append(current)
            current = ""
        elif ch == '[':
            if current:
                parts.append(current)
                current = ""
            # Find the closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                j += 1
            if j >= len(path):
                raise ValueError(f"Malformed path: unclosed bracket at position {i}")
            index_str = path[i+1:j]
            if not index_str:
                raise ValueError(f"Malformed path: empty index at position {i}")
            if index_str.startswith('-'):
                raise ValueError(f"Malformed path: negative index not allowed at position {i}")
            try:
                idx = int(index_str)
            except ValueError:
                raise ValueError(f"Malformed path: invalid index '{index_str}' at position {i}")
            parts.append(('index', idx))
            i = j  # Move to the closing bracket
        else:
            current += ch
        i += 1

    if current:
        parts.append(current)

    if not parts:
        raise ValueError("Path cannot be empty")

    # Deep copy the object to avoid modifying the original
    def deep_copy(o):
        if isinstance(o, dict):
            return {k: deep_copy(v) for k, v in o.items()}
        elif isinstance(o, list):
            return [deep_copy(v) for v in o]
        else:
            return o

    result = deep_copy(obj)

    # Navigate and build the structure
    node = result
    for step in parts[:-1]:
        if isinstance(step, tuple) and step[0] == 'index':
            idx = step[1]
            if not isinstance(node, list):
                raise TypeError(f"Expected list at path, got {type(node).__name__}")
            # Handle index within or beyond current list
            if idx < len(node):
                node = node[idx]
            elif idx == len(node):
                # Need to determine if next step is key or index
                next_step = parts[parts.index(step) + 1]
                if isinstance(next_step, tuple) and next_step[0] == 'index':
                    new_list = []
                    node.append(new_list)
                    node = new_list
                else:
                    new_dict = {}
                    node.append(new_dict)
                    node = new_dict
            else:
                # Pad with None up to idx
                while len(node) < idx:
                    node.append(None)
                next_step = parts[parts.index(step) + 1]
                if isinstance(next_step, tuple) and next_step[0] == 'index':
                    new_list = []
                    node.append(new_list)
                    node = new_list
                else:
                    new_dict = {}
                    node.append(new_dict)
                    node = new_dict
        else:
            # Key step
            if not isinstance(node, dict):
                raise TypeError(f"Expected dict at path, got {type(node).__name__}")
            if step not in node:
                # Determine next step to decide dict or list
                next_idx = parts.index(step) + 1
                if next_idx < len(parts):
                    next_step = parts[next_idx]
                    if isinstance(next_step, tuple) and next_step[0] == 'index':
                        node[step] = []
                    else:
                        node[step] = {}
                else:
                    node[step] = {}
            node = node[step]

    # Set the final value
    last_step = parts[-1]
    if isinstance(last_step, tuple) and last_step[0] == 'index':
        idx = last_step[1]
        if not isinstance(node, list):
            raise TypeError(f"Expected list at path, got {type(node).__name__}")
        if idx < len(node):
            node[idx] = value
        elif idx == len(node):
            node.append(value)
        else:
            # Pad with None up to idx, then set
            while len(node) < idx:
                node.append(None)
            node.append(value)
    else:
        if not isinstance(node, dict):
            raise TypeError(f"Expected dict at path, got {type(node).__name__}")
        node[last_step] = value

    return result
