class ProfileService:
    def __init__(self, db):
        self.db = db
        self.cache = {}
        self.db_reads = 0

    def _load(self, uid):
        self.db_reads += 1
        return dict(self.db[uid])

    def _deep_copy(self, d):
        """Return a deep copy of a dict containing only dicts and primitives."""
        if not isinstance(d, dict):
            return d
        result = {}
        for k, v in d.items():
            if isinstance(v, dict):
                result[k] = self._deep_copy(v)
            else:
                result[k] = v
        return result

    def get_profile(self, uid):
        if uid not in self.db:
            raise KeyError(uid)

        # If cache exists, return a deep copy so callers can mutate it safely
        if uid in self.cache:
            return self._deep_copy(self.cache[uid])

        # Cache miss: load from DB, store canonical version in cache, return copy
        self.cache[uid] = self._load(uid)
        return self._deep_copy(self.cache[uid])

    def update_profile(self, uid, changes):
        if uid not in self.db:
            raise KeyError(uid)

        # Load current profile from DB (not cache, to ensure we merge against latest DB state)
        profile = self._load(uid)

        # Merge changes: new keys added, existing keys replaced, nested dicts replaced as whole
        profile.update(changes)

        # Update the database
        self.db[uid] = profile

        # Update cache with the new canonical version (so next get_profile doesn't hit DB)
        self.cache[uid] = profile
