    if width < 1:
        raise ValueError("width must be at least 1")

    if not text or not text.strip():
        return []

    # Split into paragraphs by one or more blank lines
    paragraphs = []
    current_para = []

    # Split text into lines to handle paragraph breaks
    raw_lines = text.split('\n')

    for raw_line in raw_lines:
        if raw_line.strip() == "":
            # Blank line - marks paragraph break if we have content
            if current_para:
                paragraphs.append(current_para)
                current_para = []
        else:
            # Add non-blank line content to current paragraph
            current_para.append(raw_line)

    # Don't forget the last paragraph
    if current_para:
        paragraphs.append(current_para)

    result_lines = []

    for para in paragraphs:
        # Join the lines in this paragraph and split into words
        para_text = " ".join(para)
        words = para_text.split()

        if not words:
            continue

        line = ""
        para_lines = []

        for w in words:
            if len(w) > width:
                # Handle words longer than width - cut into pieces
                if line:
                    para_lines.append(line)
                    line = ""

                # Cut the long word into width-sized pieces
                while len(w) > width:
                    para_lines.append(w[:width])
                    w = w[width:]

                # Remainder starts a new line
                line = w
            elif line == "":
                # First word on the line
                line = w
            elif len(line) + 1 + len(w) <= width:
                # Word fits on current line (with space)
                line = line + " " + w
            else:
                # Word doesn't fit, start new line
                para_lines.append(line)
                line = w

        # Add the last line of the paragraph
        if line:
            para_lines.append(line)

        # Add paragraph lines to result
        if para_lines:
            if result_lines:
                result_lines.append("")  # One blank line between paragraphs
            result_lines.extend(para_lines)

    return result_lines
