                    line = w
                else:
                    # Word longer than width: cut it
                    while len(w) > width:
                        result_lines.append(w[:width])
                        w = w[width:]
                    line = w
            else:
                # Try to add to existing line
                if len(line) + 1 + len(w) <= width:
                    line += " " + w
                else:
                    # Flush current line
                    result_lines.append(line)
                    # Process the new word (might be long)
                    if len(w) <= width:
                        line = w
                    else:
                        # Cut long word
                        while len(w) > width:
                            result_lines.append(w[:width])
                            w = w[width:]
                        line = w

        if line:
            result_lines.append(line)

        # Add separator between paragraphs (one empty line)
        # But only if this isn't the last paragraph
        if para != para_blocks[-1]:
            result_lines.append("")

    return result_lines
```

The bug has three causes:
1. Keys are not normalized: `"North"` and `"north"` (and surrounding whitespace) are treated as different groups.
2. `None` values are coerced to `0` via `(value or 0)`, so missing readings incorrectly contribute zero to the sum.
3. Counts are incremented for every row, including those with `None`, so groups with only missing readings yield `0 / N = 0.0` instead of `None`.

Fix: normalize the key as `name.strip().lower()` for grouping, track the first seen original spelling (stripped) as the label, sum and count only non-`None` values, and return `None` for averages when a group has no readings.

```python
def group_averages(rows):
    sums, counts, labels = {}, {}, {}
    for name, value in rows:
        key = (name.strip().lower())
        if key not in labels:
            labels[key] = name.strip()
        if value is not None:
            sums[key] = sums.get(key, 0) + value
            counts[key] = counts.get(key, 0) + 1
    result = []
    for key in sums:
        avg = sums[key] / counts[key] if counts[key] else None
        result.append((labels[key], avg))
    # Include groups that had only None values (they have a label but no sum/count)
    for key in labels:
        if key not in sums:
            result.append((labels[key], None))
    return sorted(result, key=lambda x: x[0].lower())
```

