def group_averages(rows):
    sums = {}
    counts = {}
    first_spelling = {}

    for name, value in rows:
        # Normalize key: strip whitespace and lowercase for grouping
        key = name.strip().lower()

        # Record the first spelling seen (with whitespace stripped, but original case)
        if key not in first_spelling:
            first_spelling[key] = name.strip()

        # Initialize accumulators if new group
        if key not in sums:
            sums[key] = 0
            counts[key] = 0

        # Only process if value is not None
        if value is not None:
            sums[key] += value
            counts[key] += 1

    result = []
    for key in sums:
        label = first_spelling[key]
        if counts[key] == 0:
            average = None
        else:
            average = sums[key] / counts[key]
        result.append((label, average))

    # Sort by label ignoring case (labels are already normalized in case variation logic, 
    # but we sort by the label string itself case-insensitively to be safe)
    return sorted(result, key=lambda x: x[0].lower())
