def load_config(defaults, env, prefix="APP_"):
    """
    Build a new config dict from defaults, overridden by environment variables.

    Rules:
    - Only env keys starting with `prefix` are considered.
    - The suffix after the prefix is lowercased, then split on double underscores "__"
      to form the path. A single underscore is part of the key name.
    - The path must exist in defaults; otherwise the env var is ignored.
    - The raw string is converted to the type of the default value:
        * bool: accepts 1/true/yes/on (True) or 0/false/no/off (False), case-insensitive;
          anything else raises ValueError.
        * int/float: parsed numerically.
        * other: kept as string.
    - Returns a new dict; defaults is not modified.
    """

    def _convert(value, target_type):
        if target_type is bool:
            v = value.strip().lower()
            if v in ("1", "true", "yes", "on"):
                return True
            if v in ("0", "false", "no", "off"):
                return False
            raise ValueError(f"Invalid boolean value: {value!r}")
        if target_type is int:
            return int(value)
        if target_type is float:
            return float(value)
        # For any other type, assume string
        return str(value)

    def _deep_copy(obj):
        """Create a deep copy of nested dicts/lists without importing copy."""
        if isinstance(obj, dict):
            return {k: _deep_copy(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_deep_copy(item) for item in obj]
        return obj

    cfg = _deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Remove prefix and lowercase
        suffix = k[len(prefix):].lower()

        # Split on double underscore only
        path = suffix.split("__")

        # Traverse to the parent node
        node = cfg
        valid_path = True
        for p in path[:-1]:
            if not isinstance(node, dict) or p not in node:
                valid_path = False
                break
            node = node[p]

        if not valid_path:
            continue

        key = path[-1]
        if not isinstance(node, dict) or key not in node:
            continue

        default_value = node[key]
        target_type = type(default_value)

        try:
            converted = _convert(raw, target_type)
            node[key] = converted
        except (ValueError, TypeError):
            # Ignore variables that cannot be converted to the expected type
            continue

