def load_config(defaults, env, prefix="APP_"):
    """
    Load configuration from environment variables, overriding defaults.

    - Variables must start with `prefix` (default "APP_").
    - The suffix after the prefix is lowercased and split by double underscores "__" 
      to form nested paths (e.g., APP_DB__MAX_CONNS -> config["db"]["max_conns"]).
    - Single underscores are part of the key name, not separators.
    - Values are converted to the type of the corresponding default:
        * bool: accepts "1", "true", "yes", "on" (case-insensitive) as True;
                "0", "false", "no", "off" as False; otherwise raises ValueError.
        * int/float: parsed numerically.
        * other: kept as string.
    - Variables without the prefix or pointing to non-existent paths are ignored.
    - The defaults object is never modified.
    """
    import copy

    # Deep copy to ensure defaults is never modified
    cfg = copy.deepcopy(defaults)

    def parse_bool(value: str) -> bool:
        v = value.strip().lower()
        if v in ("1", "true", "yes", "on"):
            return True
        if v in ("0", "false", "no", "off"):
            return False
        raise ValueError(f"Invalid boolean value: {value!r}")

    def convert_value(value: str, target):
        target_type = type(target)
        if target_type is bool:
            return parse_bool(value)
        if target_type is int:
            return int(value)
        if target_type is float:
            return float(value)
        # For str or any other type, just return the raw string
        return value

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue

        # Remove prefix and split by double underscore only
        suffix = k[len(prefix):]
        path = suffix.lower().split("__")

        # Traverse the config tree
        node = cfg
        try:
            for p in path[:-1]:
                if p not in node or not isinstance(node[p], dict):
                    # Path does not exist; ignore this variable
                    break
                node = node[p]
            else:
                # Only set if the final key exists
                final_key = path[-1]
                if final_key in node:
                    node[final_key] = convert_value(raw, node[final_key])
        except (KeyError, TypeError, ValueError):
            # Ignore invalid paths or conversion errors
            continue

    return cfg
