from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, ttl):
        self.cap = capacity
        self.ttl = ttl
        self.d = OrderedDict()

    def get(self, key, now):
        if key not in self.d:
            return None
        v, exp = self.d[key]
        if now >= exp:
            del self.d[key]
            return None
        # Move to end to mark as most recently used
        self.d.move_to_end(key)
        return v

    def put(self, key, value, now):
        if self.cap <= 0:
            return
        if key in self.d:
            # Update existing: restart TTL, move to MRU, no eviction
            self.d[key] = (value, now + self.ttl)
            self.d.move_to_end(key)
            return

        # New key: first drop all expired entries
        self._drop_expired(now)

        # If still at capacity, evict LRU (oldest) live entry
        if len(self.d) >= self.cap:
            self.d.popitem(last=False)

        self.d[key] = (value, now + self.ttl)

    def size(self, now):
        # Count only live entries
        count = 0
        expired_keys = []
        for k, (v, exp) in self.d.items():
            if now >= exp:
                expired_keys.append(k)
            else:
                count += 1
        # Clean up expired entries during size check
        for k in expired_keys:
            del self.d[k]
        return count

    def _drop_expired(self, now):
