def glob_match(pattern, path):
    """
    Match a glob pattern against a path.

    Rules:
    - "*" matches any run of characters except "/" (including none)
    - "?" matches exactly one character except "/"
    - "**" matches any characters including "/"
    - "**/" matches zero or more whole directories
    - "[abc]" and "[a-c]" match one character from the set
    - "[!abc]" matches one character outside the set
    - A character class never matches "/"
    - Backslash makes the next character literal
    - Everything else is literal and case-sensitive
    - Leading dot is not special
    """

    def parse_pattern(pattern):
        """Convert glob pattern to a list of tokens."""
        tokens = []
        i = 0
        n = len(pattern)

        while i < n:
            c = pattern[i]

            if c == '\\':
                # Escape: next character is literal
                if i + 1 < n:
                    tokens.append(('LITERAL', pattern[i + 1]))
                    i += 2
                else:
                    tokens.append(('LITERAL', '\\'))
                    i += 1
            elif c == '*':
                if i + 1 < n and pattern[i + 1] == '*':
                    # "**"
                    if i + 2 < n and pattern[i + 2] == '/':
                        # "**/" - matches zero or more directories
                        tokens.append(('DOUBLESTAR_SLASH',))
                        i += 3
                    else:
                        # "**" at end or not followed by /
                        tokens.append(('DOUBLESTAR',))
                        i += 2
                else:
                    # Single "*"
                    tokens.append(('STAR',))
                    i += 1
            elif c == '?':
                tokens.append(('QUESTION',))
                i += 1
            elif c == '[':
                # Character class
                j = i + 1
                if j < n and pattern[j] == '!':
                    j += 1
                if j < n and pattern[j] == ']':
                    j += 1
                while j < n and pattern[j] != ']':
                    j += 1
                if j < n:
                    # Valid character class
                    class_content = pattern[i+1:j]
                    tokens.append(('CLASS', class_content))
                    i = j + 1
                else:
                    # Invalid class, treat as literal
                    tokens.append(('LITERAL', '['))
                    i += 1
            else:
                tokens.append(('LITERAL', c))
                i += 1

        return tokens

    def match_class(class_content, char):
        """Check if char matches the character class."""
        if not class_content:
            return False

        negate = False
        idx = 0
        if class_content[0] == '!':
            negate = True
            idx = 1

        matched = False
        while idx < len(class_content):
            c = class_content[idx]
            if c == '/' or char == '/':
                # Class never matches /
                idx += 1
                continue

            # Check for range
            if idx + 2 < len(class_content) and class_content[idx + 1] == '-':
                start = c
                end = class_content[idx + 2]
                if start <= char <= end:
                    matched = True
                idx += 3
            else:
                if c == char:
                    matched = True
                idx += 1

        return matched != negate

    def match_tokens(tokens, path, ti=0, pi=0):
        """Recursively match tokens against path."""

        while ti < len(tokens):
            token = tokens[ti]
            ttype = token[0]

            if ttype == 'LITERAL':
                if pi >= len(path) or path[pi] != token[1]:
                    return False
                pi += 1
                ti += 1
            elif ttype == 'QUESTION':
                if pi >= len(path) or path[pi] == '/':
                    return False
                pi += 1
                ti += 1
            elif ttype == 'STAR':
                # Match zero or more non-slash characters
                ti += 1
                # Try matching zero characters first, then more
                end = pi
                while end <= len(path):
                    if match_tokens(tokens, path, ti, end):
                        return True
                    if end >= len(path) or path[end] == '/':
                        break
                    end += 1
                return False
            elif ttype == 'DOUBLESTAR':
                # Match any characters including /
                ti += 1
                if ti >= len(tokens):
                    # ** at end matches everything
                    return True
                # Try matching from current position onwards
                for end in range(pi, len(path) + 1):
                    if match_tokens(tokens, path, ti, end):
                        return True
                return False
            elif ttype == 'DOUBLESTAR_SLASH':
                # Match zero or more directories (including the slash)
                ti += 1
                # Try matching zero directories (skip the **)
                if match_tokens(tokens, path, ti, pi):
                    return True
                # Try matching one or more directories
                for end in range(pi, len(path) + 1):
                    if match_tokens(tokens, path, ti, end):
                        return True
                return False
            elif ttype == 'CLASS':
                if pi >= len(path):
                    return False
                if not match_class(token[1], path[pi]):
                    return False
                pi += 1
                ti += 1
            else:
                ti += 1

        # All tokens consumed, path must also be consumed
        return pi == len(path)

    tokens = parse_pattern(pattern)
    return match_tokens(tokens, path)
