    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def _cleanup_and_sort(self, sku, today):
        """Remove expired lots and return the list sorted by expiry then insertion order."""
        if sku not in self.lots:
            return []

        # Filter out expired lots (usable while today <= expires, so expired if today > expires)
        # We modify the list in place to drop expired lots permanently
        usable_lots = []
        for lot in self.lots[sku]:
            if lot[0] >= today:
                usable_lots.append(lot)

        # Update the stored list to only contain usable lots
        self.lots[sku] = usable_lots

        # Sort by expiry date (ascending), then by original insertion order (stable sort preserves this for equal keys)
        # Since we appended in order and then filtered, the relative order of remaining items with same expiry is preserved.
        # We just need to sort by expiry.
        usable_lots.sort(key=lambda x: x[0])

        return usable_lots

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")

        usable_lots = self._cleanup_and_sort(sku, today)

        # Check if we have enough stock before modifying anything
        total_usable = sum(lot[1] for lot in usable_lots)
        if total_usable < qty:
            raise ValueError("insufficient")

        taken = []
        remaining_qty = qty

        for lot in usable_lots:
            if remaining_qty == 0:
                break

            n = min(remaining_qty, lot[1])
            lot[1] -= n
            remaining_qty -= n
            taken.append((lot[0], n))

        # Clean up empty lots from the stored list after successful take
        self.lots[sku] = [lot for lot in self.lots[sku] if lot[1] > 0]

        return taken

    def stock(self, sku, today):
        usable_lots = self._cleanup_and_sort(sku, today)
        return sum(lot[1] for lot in usable_lots)
