class Inventory:
    def __init__(self):
        self.lots = {}

    def add(self, sku, qty, expires):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.lots.setdefault(sku, []).append([expires, qty])

    def take(self, sku, qty, today):
        if qty <= 0:
            raise ValueError("qty must be positive")

        # Clean expired lots and gather usable ones
        usable = []
        remaining = []
        for lot in self.lots.get(sku, []):
            if today > lot[0]:
                # Expired, drop it
                continue
            if lot[1] > 0:
                usable.append(lot)
                remaining.append(lot)

        # Update the stored list to exclude expired lots
        if sku in self.lots:
            self.lots[sku] = remaining

        # Sort usable lots: earliest expiry first, then earliest added (stable sort preserves insertion order for ties)
        usable.sort(key=lambda x: x[0])

        # Check if we have enough stock
        total_usable = sum(lot[1] for lot in usable)
        if total_usable < qty:
            raise ValueError("insufficient")

        taken = []
        remaining_qty = qty

        for lot in usable:
            if remaining_qty == 0:
                break
            n = min(remaining_qty, lot[1])
            lot[1] -= n
            remaining_qty -= n
            taken.append((lot[0], n))

        return taken

    def stock(self, sku, today):
        total = 0
        remaining = []
        for lot in self.lots.get(sku, []):
            if today > lot[0]:
                # Expired, drop it
                continue
            if lot[1] > 0:
                total += lot[1]
                remaining.append(lot)

        # Update the stored list to exclude expired lots
        if sku in self.lots:
            self.lots[sku] = remaining

        return total
