def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    The original `obj` and everything reachable from it is left untouched.

    Rules:
    - Path is dot-separated keys with optional list indexes (e.g., "a.b[2].c").
    - Missing dict keys are created as dicts.
    - Missing list indices are created as lists; index == len appends; index > len pads with None.
    - Type mismatch (key step on list/scalar, index step on dict/scalar) raises TypeError.
    - Empty or malformed path raises ValueError.
    - First step must be a key; obj must be a dict.
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate path format before processing
    # Check for leading/trailing dots, double dots, unclosed brackets, negative indices, non-numeric indices
    if path.startswith('.') or path.endswith('.'):
        raise ValueError("path cannot start or end with a dot")

    if '..' in path:
        raise ValueError("path cannot contain empty keys (double dots)")

    # Parse path into steps
    # We need to handle "a.b[2].c" -> ['a', 'b', '[2]', 'c']
    # But also ensure we don't split inside brackets incorrectly
    steps = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current == "":
                raise ValueError("empty key in path")
            steps.append(current)
            current = ""
        elif ch == '[':
            if current != "":
                steps.append(current)
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                j += 1
            if j == len(path):
                raise ValueError("unclosed bracket in path")
            bracket_content = path[i+1:j]
            if bracket_content == "":
                raise ValueError("empty index in path")
            if bracket_content.startswith('-'):
                raise ValueError("negative indices not supported")
            if not bracket_content.isdigit():
                raise ValueError("index must be a non-negative integer")
            steps.append(f"[{bracket_content}]")
            i = j  # will be incremented at end of loop
        else:
            current += ch
        i += 1

    if current != "":
        steps.append(current)

    if not steps:
        raise ValueError("path is empty or malformed")

    # First step must be a key (not an index)
    if steps[0].startswith('['):
        raise ValueError("first step must be a key")

    # Deep copy function for dict/list structures
    def deep_copy(o):
        if isinstance(o, dict):
            return {k: deep_copy(v) for k, v in o.items()}
        elif isinstance(o, list):
            return [deep_copy(item) for item in o]
        else:
            return o

    # Create a deep copy to avoid mutating the original
    result = deep_copy(obj)

    # Navigate and build the structure
    node = result

    # Process all steps except the last one
    for idx in range(len(steps) - 1):
        step = steps[idx]
        next_step = steps[idx + 1]

        if step.startswith('['):
            # Index step
            index = int(step[1:-1])
            if not isinstance(node, list):
                raise TypeError(f"expected list for index step, got {type(node).__name__}")

            # Handle index out of bounds
            if index == len(node):
                # Append new container based on next step
                if next_step.startswith('['):
                    node.append([])
                else:
                    node.append({})
            elif index > len(node):
                # Pad with None up to index, then append appropriate container
                while len(node) < index:
                    node.append(None)
                if next_step.startswith('['):
                    node.append([])
                else:
                    node.append({})
            # If index < len(node), we just access it (may be None or existing value)

            if node[index] is None:
                # Create appropriate container based on next step
                if next_step.startswith('['):
                    node[index] = []
                else:
                    node[index] = {}
            elif next_step.startswith('[') and not isinstance(node[index], list):
                raise TypeError(f"expected list for index step, got {type(node[index]).__name__}")
            elif not next_step.startswith('[') and not isinstance(node[index], dict):
                raise TypeError(f"expected dict for key step, got {type(node[index]).__name__}")

            node = node[index]
        else:
            # Key step
            if not isinstance(node, dict):
                raise TypeError(f"expected dict for key step, got {type(node).__name__}")

            if step not in node:
                # Create appropriate container based on next step
                if next_step.startswith('['):
                    node[step] = []
                else:
                    node[step] = {}
            elif next_step.startswith('[') and not isinstance(node[step], list):
                raise TypeError(f"expected list for index step, got {type(node[step]).__name__}")
            elif not next_step.startswith('[') and not isinstance(node[step], dict):
                raise TypeError(f"expected dict for key step, got {type(node[step]).__name__}")

            node = node[step]

    # Handle the last step (set the value)
    last_step = steps[-1]

    if last_step.startswith('['):
        # Index step for final assignment
        index = int(last_step[1:-1])
        if not isinstance(node, list):
            raise TypeError(f"expected list for index step, got {type(node).__name__}")

        if index == len(node):
            node.append(value)
        elif index > len(node):
            # Pad with None up to index
            while len(node) < index:
                node.append(None)
            node.append(value)
        else:
            node[index] = value
    else:
        # Key step for final assignment
        if not isinstance(node, dict):
            raise TypeError(f"expected dict for key step, got {type(node).__name__}")
        node[last_step] = value

    return result
