class ProfileService:
    def __init__(self, db):
        self.db = db
        self.cache = {}
        self.db_reads = 0

    def _load(self, uid):
        self.db_reads += 1
        # Deep copy nested structures to prevent mutation of the store
        def deep_copy(obj):
            if isinstance(obj, dict):
                return {k: deep_copy(v) for k, v in obj.items()}
            elif isinstance(obj, list):
                return [deep_copy(item) for item in obj]
            else:
                return obj
        return deep_copy(self.db[uid])

    def get_profile(self, uid):
        if uid not in self.cache:
            self.cache[uid] = self._load(uid)
        # Return a deep copy so callers can mutate without affecting cache/store
        def deep_copy(obj):
            if isinstance(obj, dict):
                return {k: deep_copy(v) for k, v in obj.items()}
            elif isinstance(obj, list):
                return [deep_copy(item) for item in obj]
            else:
                return obj
        return deep_copy(self.cache[uid])

    def update_profile(self, uid, changes):
        if uid not in self.db:
            raise KeyError(uid)

        # Load current profile from DB (bypassing cache to ensure we have latest DB state)
        profile = self._load(uid)

        # Merge changes: new keys added, existing keys replaced, nested dicts replaced as whole
        for key, value in changes.items():
            profile[key] = value

        # Update the database
        self.db[uid] = profile

        # Invalidate cache for this uid so next get_profile reloads from DB
        if uid in self.cache:
            del self.cache[uid]
