class Bus:
    def __init__(self):
        self.subs = {}

    def on(self, topic, handler, priority=0):
        if topic not in self.subs:
            self.subs[topic] = []
        entry = (priority, handler)
        self.subs[topic].append(entry)
        # Sort: higher priority first (descending), stable for equal priorities (subscription order)
        self.subs[topic].sort(key=lambda p: p[0], reverse=True)

        # Return an unsubscribe function that removes only this specific subscription
        def unsubscribe():
            if topic in self.subs:
                try:
                    self.subs[topic].remove(entry)
                except ValueError:
                    # Already unsubscribed; harmless
                    pass

        return unsubscribe

    def emit(self, topic, *args):
        if topic not in self.subs:
            return 0

        # Snapshot the current list of handlers to avoid issues with modifications during emit
        snapshot = list(self.subs[topic])
        n = 0
        for _, h in snapshot:
            # Check if this handler is still subscribed (in case it was unsubscribed by an earlier handler)
            if ( _, h) in self.subs[topic]:
                h(*args)
                n += 1
        return n
