class Bus:
    def __init__(self):
        self.subs = {}
        self._emitting = {}  # topic -> set of ids currently being emitted

    def on(self, topic, handler, priority=0):
        if topic not in self.subs:
            self.subs[topic] = []

        # Create a unique subscription entry with an id to handle duplicate handlers
        sub_id = id(handler) * (len(self.subs[topic]) + 1) + len(self.subs[topic])
        entry = {'priority': priority, 'handler': handler, 'id': sub_id, 'active': True}
        self.subs[topic].append(entry)

        # Sort: higher priority first, then by subscription order (stable for equal priority)
        # We use negative priority for descending order, and the original list order preserves subscription order
        self.subs[topic].sort(key=lambda x: (-x['priority'], self.subs[topic].index(x)))

        def unsubscribe():
            # Find and mark as inactive rather than removing immediately
            for sub in self.subs.get(topic, []):
                if sub['id'] == sub_id and sub['active']:
                    sub['active'] = False
                    break
            # If currently emitting, clean up inactive entries after emit
            if topic in self._emitting and self._emitting[topic]:
                # Will be cleaned up after emit completes
                pass
            else:
                # Clean up inactive entries if not emitting
                self.subs[topic] = [s for s in self.subs[topic] if s['active']]
                if not self.subs[topic]:
                    del self.subs[topic]

        return unsubscribe

    def emit(self, topic, *args):
        if topic not in self.subs:
            return 0

        # Mark that we're emitting this topic
        self._emitting[topic] = True

        # Get snapshot of active handlers in correct order
        handlers_to_call = []
        for sub in self.subs[topic]:
            if sub['active']:
                handlers_to_call.append(sub['handler'])

        n = 0
        for handler in handlers_to_call:
            # Check if still active (might have been unsubscribed by earlier handler)
            still_active = False
            for sub in self.subs.get(topic, []):
                if sub['handler'] == handler and sub['active']:
                    still_active = True
                    break

            if still_active:
                handler(*args)
                n += 1

        # Clean up inactive entries after emit
        if topic in self.subs:
            self.subs[topic] = [s for s in self.subs[topic] if s['active']]
            if not self.subs[topic]:
                del self.subs[topic]

        self._emitting[topic] = False
        if not any(self._emitting.values()):
            self._emitting.clear()

        return n
