def wrap(text, width):
    if width < 1:
        raise ValueError("width must be at least 1")

    if not text or not text.strip():
        return []

    # Split text into paragraphs based on blank lines
    paragraphs = []
    current_para_lines = []

    # We need to process the text preserving paragraph structure.
    # The spec says: "Paragraphs are separated by one or more blank lines; 
    # the result has exactly one '' between paragraphs."
    # And "Empty or blank text gives []".

    # Let's split the raw text by lines first to detect paragraph breaks
    raw_lines = text.splitlines()

    para_blocks = []
    current_block = []

    for line in raw_lines:
        if line.strip() == "":
            if current_block:
                para_blocks.append(" ".join(current_block))
                current_block = []
            # If we encounter multiple blank lines, they just separate paragraphs.
            # We only care that there was a break.
        else:
            # Collapse whitespace within the line as per "Words are separated by any whitespace (runs collapse to one space)"
            # Actually, the split() method later will handle collapsing runs of whitespace.
            # But we need to group non-blank lines into paragraphs.
            current_block.append(line)

    if current_block:
        para_blocks.append(" ".join(current_block))

    if not para_blocks:
        return []

    result_lines = []

    for idx, para in enumerate(para_blocks):
        # Process each paragraph
        words = para.split()
        if not words:
            continue

        current_line = ""

        for word in words:
            # Handle words longer than width by cutting them
            while len(word) > width:
                # If there's content in current_line, push it first
                if current_line:
                    result_lines.append(current_line)
                    current_line = ""

                # Take a chunk of size 'width'
                chunk = word[:width]
                result_lines.append(chunk)
                word = word[width:]

            # Now word fits in width (or is empty after cutting)
            if not word:
                continue

            if current_line == "":
                current_line = word
            else:
                # Check if adding this word exceeds width
                # "a line of exactly `width` characters is fine"
                if len(current_line) + 1 + len(word) <= width:
                    current_line += " " + word
                else:
                    result_lines.append(current_line)
                    current_line = word

        if current_line:
            result_lines.append(current_line)

        # Add exactly one empty line between paragraphs
        if idx < len(para_blocks) - 1:
            result_lines.append("")

    return result_lines
```

