def wrap(text, width):
    if width < 1:
        raise ValueError("width must be >= 1")

    if not text or not text.strip():
        return []

    # Split into paragraphs by one or more blank lines
    paragraphs = []
    current_para = []
    for line in text.splitlines():
        if not line.strip():
            if current_para:
                paragraphs.append(" ".join(current_para))
                current_para = []
        else:
            current_para.extend(line.split())
    if current_para:
        paragraphs.append(" ".join(current_para))

    result = []
    for para in paragraphs:
        words = para.split()
        line = ""
        for w in words:
            if not line:
                # Start new line with this word (or piece)
                if len(w) <= width:
                    line = w
                else:
                    # Word longer than width: take first 'width' chars
                    line = w[:width]
                    result.append(line)
                    w = w[width:]
                    if w:
                        line = w
                    else:
                        line = ""
            else:
                # Try to add word to current line
                if len(line) + 1 + len(w) <= width:
                    line = line + " " + w
                else:
                    # Flush current line
                    result.append(line)
                    # Now handle the word (may need splitting)
                    if len(w) <= width:
                        line = w
                    else:
                        # Split long word
                        while len(w) > width:
                            result.append(w[:width])
                            w = w[width:]
                        line = w if w else ""
        if line:
            result.append(line)
        # Add blank line between paragraphs (but not after the last)
        result.append("")

    # Remove trailing empty string if present
    if result and result[-1] == "":
        result.pop()

    return result
