        # Normalize the name: strip whitespace and convert to lowercase for grouping
        normalized = name.strip().lower()

        # Track the first original spelling (with whitespace stripped) for the label
        if normalized not in first_seen:
            first_seen[normalized] = name.strip()

        # Initialize accumulators if this is the first time seeing this group
