def group_averages(rows):
    sums = {}
    counts = {}
    first_seen = {}

    for name, value in rows:
        # Normalize key: strip whitespace and lowercase for grouping
        key = name.strip().lower()

        # Track the first spelling seen (with whitespace stripped) for the label
        if key not in first_seen:
            first_seen[key] = name.strip()

        # Initialize accumulators if this is the first time seeing this group
        if key not in sums:
            sums[key] = 0
            counts[key] = 0

        # Handle value: None means "no reading" (ignore completely)
        if value is not None:
            sums[key] += value
            counts[key] += 1

    result = []
    for key in sums:
        label = first_seen[key]
        if counts[key] == 0:
            # Group with no readings has average None
            average = None
        else:
            average = sums[key] / counts[key]
        result.append((label, average))

    # Sort by name ignoring case (key is already lowercased, but sort by label case-insensitively)
    # The requirement says "sorted by name ignoring case". 
    # Since our keys are normalized, we can sort by the key itself which is lowercase.
    # However, to be safe and explicit about sorting by the original label ignoring case:
    result.sort(key=lambda x: x[0].lower())

    return result
