def load_config(defaults, env, prefix="APP_"):
    def parse_value(raw, template):
        if isinstance(template, bool):
            low = raw.lower()
            if low in ("1", "true", "yes", "on"):
                return True
            if low in ("0", "false", "no", "off"):
                return False
            raise ValueError(f"Invalid boolean value: {raw}")
        if isinstance(template, int):
            return int(raw)
        if isinstance(template, float):
            return float(raw)
        return raw

    def deep_copy(obj):
        if isinstance(obj, dict):
            return {k: deep_copy(v) for k, v in obj.items()}
        return obj

    cfg = deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
            continue
        suffix = k[len(prefix):]
        # Split only on double underscores for nesting; single underscores are part of the key
        path = suffix.lower().split("__")

        # Traverse to the parent node
        node = cfg
        valid_path = True
        for p in path[:-1]:
            if p not in node or not isinstance(node[p], dict):
                valid_path = False
                break
            node = node[p]

        if not valid_path:
            continue

        final_key = path[-1]
        if final_key not in node:
            continue

        try:
            node[final_key] = parse_value(raw, node[final_key])
        except ValueError:
            raise

    return cfg
```

The bugs are:
1. `cfg = dict(defaults)` is a shallow copy, so nested dicts are shared and the original `defaults` is mutated.
2. The path splitting uses `_` for everything, so keys that legitimately contain underscores (like `max_conns`) are split incorrectly. The spec requires `__` as the nesting separator.
3. There is no check for whether the path exists in the defaults, causing crashes on unknown variables.
4. The type conversion for `bool` is missing; it just tries `bool(raw)` which would be truthy for any non-empty string.
5. Unknown variables (paths not in defaults) should be ignored, not crash.
6. The observed bug "APP_DEBUG=false turns debugging on" confirms the bool parsing is broken.

Here is the corrected module:

```python
def load_config(defaults, env, prefix="APP_"):
    def deep_copy(obj):
        if isinstance(obj, dict):
            return {k: deep_copy(v) for k, v in obj.items()}
        return obj

    def parse_bool(raw):
        if raw.lower() in ("1", "true", "yes", "on"):
            return True
        if raw.lower() in ("0", "false", "no", "off"):
            return False
        raise ValueError(f"Invalid boolean value: {raw}")

    def convert_value(default_val, raw):
        if isinstance(default_val, bool):
            return parse_bool(raw)
        if isinstance(default_val, int):
            return int(raw)
        if isinstance(default_val, float):
            return float(raw)
        return raw

    def set_nested(cfg, path, value):
        node = cfg
        for key in path[:-1]:
            node = node[key]
        node[path[-1]] = value

    def get_nested(defaults, path):
        node = defaults
        for key in path:
            if not isinstance(node, dict) or key not in node:
                return None
            node = node[key]
        return node

    cfg = deep_copy(defaults)
    for k, raw in env.items():
        if not k.startswith(prefix):
            continue
        path_key = k[len(prefix):]
        path = path_key.lower().split("__")

        # Check if path exists in defaults
        if get_nested(defaults, path) is None:
            continue

        try:
            default_val = get_nested(defaults, path)
            converted = convert_value(default_val, raw)
            set_nested(cfg, path, converted)
        except (ValueError, TypeError):
            raise

    return cfg
```

```python
def load_config(defaults, env, prefix="APP_"):
    """
    Load configuration from environment variables, overriding defaults.

    - Variables must start with `prefix` (default "APP_").
    - The suffix after the prefix is lowercased and split by double underscores "__" 
      to form nested paths (e.g., APP_DB__MAX_CONNS -> config["db"]["max_conns"]).
    - Single underscores are part of the key name, not separators.
    - Values are converted to the type of the corresponding default:
        * bool: accepts "1", "true", "yes", "on" (case-insensitive) as True;
                "0", "false", "no", "off" as False; raises ValueError otherwise.
        * int/float: parsed numerically.
        * other: kept as string.
    - Variables without the prefix or pointing to non-existent paths are ignored.
    - The defaults object is not modified.
    """
    def deep_copy(obj):
        if isinstance(obj, dict):
            return {k: deep_copy(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [deep_copy(item) for item in obj]
        else:
            return obj

    def convert_value(value, target_type):
        if target_type is bool:
            lower_val = value.lower()
            if lower_val in ("1", "true", "yes", "on"):
                return True
            elif lower_val in ("0", "false", "no", "off"):
                return False
            else:
                raise ValueError(f"Invalid boolean value: {value}")
        elif target_type is int:
            return int(value)
        elif target_type is float:
            return float(value)
        else:
            return target_type(value)

    cfg = deep_copy(defaults)

    for k, raw in env.items():
        if not k.startswith(prefix):
