        suffix = k[len(prefix):]
        path = suffix.lower().split("__")

        node = cfg
        valid_path = True

        for p in path[:-1]:
            if p not in node or not isinstance(node[p], dict):
                valid_path = False
                break
            node = node[p]

        if not valid_path:
            continue

        final_key = path[-1]
        if final_key not in node:
            continue

        try:
            target_type = type(node[final_key])
            node[final_key] = convert_value(raw, target_type)
        except (ValueError, TypeError):
            raise ValueError(f"Cannot convert '{raw}' to {target_type.__name__} for key '{k}'")

