import re


def evaluate(s):
    # Tokenize: numbers (int/float), operators, parentheses. Ignore spaces.
    token_pattern = r"\d+\.?\d*|\.\d+|[-+*/^()]"
    raw_tokens = re.findall(token_pattern, s)

    # Validate: reconstitute non-space chars and compare to original (minus spaces)
    # This catches unknown characters like '$'
    cleaned_input = s.replace(" ", "")
    reconstructed = "".join(raw_tokens)
    if reconstructed != cleaned_input:
        raise ValueError("Invalid characters in expression")

    if not raw_tokens:
        raise ValueError("Empty expression")

    toks = raw_tokens
    pos = 0
    len_toks = len(toks)

    def peek():
        return toks[pos] if pos < len_toks else None

    def take():
        nonlocal pos
        if pos >= len_toks:
            raise ValueError("Unexpected end of expression")
        t = toks[pos]
        pos += 1
        return t

    def expect(token):
        if peek() != token:
            raise ValueError(f"Expected '{token}'")
        take()

    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            if op == "+":
                v = v + r
            else:
                v = v - r
        return v

    def term():
        v = power()
        while peek() in ("*", "/"):
            op = take()
            r = power()
            if op == "*":
                v = v * r
            else:
                if r == 0:
                    raise ZeroDivisionError("division by zero")
                v = v / r
        return v

    def power():
        # Unary binds tighter than ^, but ^ is right associative.
        # Grammar: power -> unary ('^' power)?
        # This handles right associativity: 2^3^2 -> 2^(3^2)
        v = unary()
        if peek() == "^":
            take()
            exponent = power()  # Recursive for right-associativity
            v = v ** exponent
        return v

    def unary():
        # Handles unary + and -
        if peek() == "+":
            take()
            return unary()
        if peek() == "-":
            take()
            return -unary()
        return atom()

    def atom():
        t = peek()
        if t is None:
            raise ValueError("Missing operand")

        if t == "(":
            take()
            v = expr()
            expect(")")
            return v

        if t in ("+", "-", "*", "/", "^"):
            raise ValueError(f"Unexpected operator '{t}'")

        # Must be a number
        take()
        return float(t)

    result = expr()

    if pos != len_toks:
        raise ValueError("Unexpected input after expression")

    return result
