I'll analyze the bugs and fix them systematically using test-driven development.

## Bug Analysis

1. **`-2^2` gives 4 instead of -4**: The issue is that unary minus is handled in `atom()`, but exponentiation (`^`) should bind tighter than unary minus. Currently, `-2^2` is parsed as `(-2)^2 = 4` instead of `-(2^2) = -4`.

2. **`2^3^2` gives 64 instead of 512**: Exponentiation should be right-associative (`2^(3^2) = 2^9 = 512`), but the current `while` loop makes it left-associative (`(2^3)^2 = 8^2 = 64`).

3. **Garbage like "2 $ 3" or "(2" is silently accepted**: The tokenizer doesn't validate unknown characters, and there's no check for unmatched parentheses or invalid token sequences.

4. **Missing validation**: No checks for empty input, two numbers in a row, missing operands, etc.

Let me write the corrected module:

```python
import re


def evaluate(s):
    if not s or not s.strip():
        raise ValueError("Empty expression")

    # Tokenize: numbers (including decimals), operators, parentheses
    # Also capture any invalid characters to detect them
    token_pattern = r"\d+\.?\d*|\.\d+|[-+*/^()]"
    toks = re.findall(token_pattern, s)

    # Check if the entire string (minus whitespace) is covered by valid tokens
    # Rebuild what we tokenized and compare
    reconstructed = "".join(toks)
    original_no_space = re.sub(r"\s+", "", s)

    if reconstructed != original_no_space:
        raise ValueError("Invalid characters in expression")

    if not toks:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def take():
        nonlocal pos
        t = peek()
        pos += 1
        return t

    def expect(token):
        t = take()
        if t != token:
            raise ValueError(f"Expected {token}, got {t}")
        return t

    def expr():
        """Handle + and - (lowest precedence, left-to-right)"""
        v = term()
        while peek() in ("+", "-"):
            op = take()
            r = term()
            if v is None or r is None:
                raise ValueError("Missing operand")
            v = v + r if op == "+" else v - r
        return v

    def term():
        """Handle * and / (higher precedence, left-to-right)"""
        v = power()
        while peek() in ("*", "/"):
            op = take()
            r = power()
            if v is None or r is None:
                raise ValueError("Missing operand")
            if op == "/" and r == 0:
                raise ZeroDivisionError("Division by zero")
            v = v * r if op == "*" else v / r
        return v

    def power():
        """Handle ^ (highest binary precedence, right-associative)"""
        v = unary()
        if peek() == "^":
            take()  # consume ^
            # Right-associative: recursively parse the rest as power
            exp = power()
            if v is None or exp is None:
                raise ValueError("Missing operand")
            v = v ** exp
        return v

    def unary():
        """Handle unary + and - (tighter than + - * /, looser than ^)"""
        t = peek()
        if t == "+":
            take()
            return unary()
        if t == "-":
            take()
            return -unary()
        return atom()

    def atom():
        """Handle numbers and parenthesized expressions"""
        t = peek()
        if t is None:
            raise ValueError("Unexpected end of expression")
        if t == "(":
            take()  # consume (
            v = expr()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            take()  # consume )
            return v
        if t in ("+", "-", "*", "/", "^"):
            raise ValueError(f"Unexpected operator: {t}")
        # Must be a number
        take()
        return float(t)

    result = expr()

    # Check that we consumed all tokens
    if pos < len(toks):
        raise ValueError(f"Unexpected token: {toks[pos]}")

    return result
```

