from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, ttl):
        self.cap = capacity
        self.ttl = ttl
        self.d = OrderedDict()

    def _clean_expired(self, now):
        """Remove all expired entries."""
        expired_keys = [k for k, (v, exp) in self.d.items() if now >= exp]
        for k in expired_keys:
            del self.d[k]

    def get(self, key, now):
        if key not in self.d:
            return None
        v, exp = self.d[key]
        if now >= exp:
            del self.d[key]
            return None
        # Move to end to mark as most recently used
        self.d.move_to_end(key)
        return v

    def put(self, key, value, now):
        if self.cap <= 0:
            return

        if key in self.d:
            # Update existing key: replace value, restart TTL, move to end
            self.d[key] = (value, now + self.ttl)
            self.d.move_to_end(key)
            return

        # New key: first drop expired entries
        self._clean_expired(now)

        # If still full, evict LRU live entry
        if len(self.d) >= self.cap:
            self.d.popitem(last=False)

        self.d[key] = (value, now + self.ttl)

    def size(self, now):
        self._clean_expired(now)
        return len(self.d)
