    The original obj and everything reachable from it is left untouched.
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or path.startswith(".") or path.endswith("."):
        raise ValueError("Path is empty or malformed")

    # Validate and parse path
    parts = []
    current = ""
    i = 0
    while i < len(path):
        char = path[i]
        if char == '.':
            if current == "":
                raise ValueError("Path is malformed (empty key)")
            parts.append(('key', current))
            current = ""
        elif char == '[':
            if current != "":
                parts.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                if path[j] == '[':  # Nested brackets not allowed in simple format
                    raise ValueError("Path is malformed")
                j += 1
            if j >= len(path):
                raise ValueError("Path is malformed (unclosed bracket)")

            index_str = path[i+1:j]
            if not index_str.isdigit() and (not index_str.startswith('-') or not index_str[1:].isdigit()):
                # Check for negative numbers specifically
                if index_str.startswith('-') and index_str[1:].isdigit():
                     pass # Allow negative for now, will check logic later
                else:
                    raise ValueError("Path is malformed (non-numeric index)")

            if index_str.startswith('-'):
                 raise ValueError("Path is malformed (negative index)")

            if not index_str.isdigit():
                raise ValueError("Path is malformed (non-numeric index)")

            parts.append(('index', int(index_str)))
            i = j # Move to ']'
        else:
            current += char
        i += 1

    if current != "":
        parts.append(('key', current))

    if not parts:
        raise ValueError("Path is empty")

    # First step must be a key
    if parts[0][0] != 'key':
        raise ValueError("First step must be a key")

    # Deep copy function to ensure immutability of original
    def deep_copy(item):
        if isinstance(item, dict):
            return {k: deep_copy(v) for k, v in item.items()}
        elif isinstance(item, list):
            return [deep_copy(v) for v in item]
        else:
            return item

    result = deep_copy(obj)

    node = result

    # Navigate to the parent of the target location
    for i in range(len(parts) - 1):
        step_type, step_val = parts[i]

        if step_type == 'key':
            if not isinstance(node, dict):
                raise TypeError("Cannot use key on non-dict")
            if step_val not in node:
                # Determine next step type to decide what to create
                next_type, _ = parts[i+1]
                if next_type == 'key':
                    node[step_val] = {}
                else:
                    node[step_val] = []
            node = node[step_val]
        else: # index
            if not isinstance(node, list):
                raise TypeError("Cannot use index on non-list")

            idx = step_val
            if idx > len(node):
                # Pad with None
                node.extend([None] * (idx - len(node)))
            elif idx == len(node):
                node.append(None)

            if node[idx] is None:
                # Determine next step type
                next_type, _ = parts[i+1]
                if next_type == 'key':
                    node[idx] = {}
                else:
                    node[idx] = []

            node = node[idx]

    # Set the final value
    last_type, last_val = parts[-1]

    if last_type == 'key':
        if not isinstance(node, dict):
            raise TypeError("Cannot set key on non-dict")
        node[last_val] = value
    else: # index
        if not isinstance(node, list):
            raise TypeError("Cannot set index on non-list")

        idx = last_val
        if idx > len(node):
            node.extend([None] * (idx - len(node)))
        elif idx == len(node):
            node.append(None)

        node[idx] = value

    return result
