def glob_match(pattern, path):
    """
    Match a glob pattern against a path.

    Rules:
    - "*" matches any run of characters except "/" (including none)
    - "?" matches exactly one character except "/"
    - "**" matches any characters including "/"
    - "**/" matches zero or more whole directories
    - "[abc]" matches one character from the set
    - "[a-c]" matches one character in the range
    - "[!abc]" matches one character outside the set
    - A character class never matches "/"
    - Backslash makes the next character literal
    - Everything else is literal and case-sensitive
    - Leading dot is not special
    """

    def parse_pattern(pattern):
        """Convert glob pattern to a list of tokens."""
        tokens = []
        i = 0
        n = len(pattern)

        while i < n:
            c = pattern[i]

            if c == '\\':
                # Escape: next character is literal
                if i + 1 < n:
                    tokens.append(('LITERAL', pattern[i + 1]))
                    i += 2
                else:
                    tokens.append(('LITERAL', '\\'))
                    i += 1
            elif c == '*':
                if i + 1 < n and pattern[i + 1] == '*':
                    # "**"
                    if i + 2 < n and pattern[i + 2] == '/':
                        # "**/" - matches zero or more directories
                        tokens.append(('DOUBLESTAR_SLASH',))
                        i += 3
                    else:
                        # "**" at end or not followed by /
                        tokens.append(('DOUBLESTAR',))
                        i += 2
                else:
                    # Single "*"
                    tokens.append(('STAR',))
                    i += 1
            elif c == '?':
                tokens.append(('QUESTION',))
                i += 1
            elif c == '[':
                # Character class
                j = i + 1
                if j < n and pattern[j] == '!':
                    j += 1
                if j < n and pattern[j] == ']':
                    j += 1
                while j < n and pattern[j] != ']':
                    j += 1
                if j < n:
                    class_content = pattern[i+1:j]
                    tokens.append(('CLASS', class_content))
                    i = j + 1
                else:
                    # Unclosed bracket, treat as literal
                    tokens.append(('LITERAL', '['))
                    i += 1
            else:
                tokens.append(('LITERAL', c))
                i += 1

        return tokens

    def match_class(class_content, char):
        """Check if char matches the character class."""
        if not class_content:
            return False

        negated = False
        idx = 0
        if class_content[0] == '!':
            negated = True
            idx = 1

        matches = False
        while idx < len(class_content):
            c = class_content[idx]
            if idx + 2 < len(class_content) and class_content[idx + 1] == '-':
                # Range
                end_char = class_content[idx + 2]
                if c <= char <= end_char:
                    matches = True
                idx += 3
            else:
                if c == char:
                    matches = True
                idx += 1

        return matches != negated

    def match_tokens(tokens, path, p_idx=0, s_idx=0, memo=None):
        """Recursive matching with memoization."""
        if memo is None:
            memo = {}

        key = (p_idx, s_idx)
        if key in memo:
            return memo[key]

        # Base cases
        if p_idx == len(tokens):
            result = s_idx == len(path)
            memo[key] = result
            return result

        token = tokens[p_idx]
        token_type = token[0]

        if token_type == 'LITERAL':
            lit_char = token[1]
            if s_idx < len(path) and path[s_idx] == lit_char:
                result = match_tokens(tokens, path, p_idx + 1, s_idx + 1, memo)
            else:
                result = False
        elif token_type == 'STAR':
            # Matches any characters except "/"
            result = False
            # Try matching zero or more non-slash characters
            j = s_idx
            while j <= len(path):
                if match_tokens(tokens, path, p_idx + 1, j, memo):
                    result = True
                    break
                if j < len(path) and path[j] == '/':
                    break
                j += 1
        elif token_type == 'QUESTION':
            # Matches exactly one character except "/"
            if s_idx < len(path) and path[s_idx] != '/':
                result = match_tokens(tokens, path, p_idx + 1, s_idx + 1, memo)
            else:
                result = False
        elif token_type == 'CLASS':
            class_content = token[1]
            if s_idx < len(path) and path[s_idx] != '/':
                if match_class(class_content, path[s_idx]):
                    result = match_tokens(tokens, path, p_idx + 1, s_idx + 1, memo)
                else:
                    result = False
            else:
                result = False
        elif token_type == 'DOUBLESTAR':
            # Matches any characters including "/"
            result = False
            for j in range(s_idx, len(path) + 1):
                if match_tokens(tokens, path, p_idx + 1, j, memo):
                    result = True
                    break
        elif token_type == 'DOUBLESTAR_SLASH':
            # Matches zero or more directories (including the trailing slash)
            # Can match: "", "dir/", "dir1/dir2/", etc.
            result = False
            # Try matching zero directories (consume nothing)
            if match_tokens(tokens, path, p_idx + 1, s_idx, memo):
                result = True
            else:
                # Try matching one or more directories
                j = s_idx
                while j < len(path):
                    if path[j] == '/':
                        j += 1
                        if match_tokens(tokens, path, p_idx + 1, j, memo):
                            result = True
                            break
                    j += 1
        else:
            result = False

        memo[key] = result
        return result

    tokens = parse_pattern(pattern)
    return match_tokens(tokens, path)
