def set_path(obj, path, value):
    """
    Return a new structure where the location named by `path` holds `value`.
    `obj` and everything reachable from it is left untouched (deep copy).

    Path format: dot-separated keys with optional list indexes.
    Examples: "a.b[2].c", "items[0]"

    Rules:
    - Missing dict keys are created as dicts.
    - Missing containers for index steps are created as lists.
    - Index == len(list) appends; index > len(list) pads with None.
    - Type mismatch (key step on list/scalar, index step on dict/scalar) raises TypeError.
    - Empty, malformed paths raise ValueError.
    - First step must be a key; obj must be a dict.
    """
    import copy

    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate and parse path
    # Check for malformed patterns
    if path.startswith(".") or path.endswith("."):
        raise ValueError("path cannot start or end with '.'")
    if ".." in path:
        raise ValueError("path cannot contain empty segments ('..')")
    if "[" in path and "]" not in path:
        raise ValueError("unclosed bracket in path")
    if "]" in path and "[" not in path:
        raise ValueError("unmatched closing bracket")

    # Split into segments, handling both dots and brackets
    # We need to carefully parse "a.b[2].c" -> ["a", "b", "[2]", "c"]
    segments = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == ".":
            if current:
                segments.append(current)
                current = ""
            # Check for empty segment (handled by startswith/endswith and .. check above)
        elif ch == "[":
            if current:
                segments.append(current)
                current = ""
            # Find matching ]
            j = i + 1
            while j < len(path) and path[j] != "]":
                j += 1
            if j >= len(path):
                raise ValueError("unclosed bracket in path")
            bracket_content = path[i:j+1]  # includes [ and ]
            # Validate bracket content: must be [N] where N is non-negative integer
            inner = bracket_content[1:-1]
            if not inner:
                raise ValueError("empty bracket index")
            if not inner.isdigit():
                raise ValueError("bracket index must be a non-negative integer")
            if inner.startswith("0") and len(inner) > 1:
                # Allow "0" but not "01", etc. Actually, let's allow leading zeros for simplicity
                # but standard Python int() allows them. Let's just use int().
                pass
            segments.append(bracket_content)
            i = j  # will be incremented below
        else:
            current += ch
        i += 1

    if current:
        segments.append(current)

    if not segments:
        raise ValueError("path is empty or malformed")

    # First segment must be a key (not an index)
    if segments[0].startswith("["):
        raise ValueError("first step must be a key")

    # Deep copy to ensure immutability of original
    result = copy.deepcopy(obj)

    node = result

    # Navigate/create path up to the second-to-last segment
    for idx, seg in enumerate(segments[:-1]):
        next_seg = segments[idx + 1]
        is_next_index = next_seg.startswith("[")

        if seg.startswith("["):
            # Index step
            index = int(seg[1:-1])
            if not isinstance(node, list):
                raise TypeError(f"expected list at step, got {type(node).__name__}")

            # Handle index
            if index == len(node):
                # Append new container
                if is_next_index:
                    node.append([])
                else:
                    node.append({})
            elif index > len(node):
                # Pad with None then append
                while len(node) < index:
                    node.append(None)
                if is_next_index:
                    node.append([])
                else:
                    node.append({})
            # If index < len(node), we just access it (may be None or existing)

            if node[index] is None:
                if is_next_index:
                    node[index] = []
                else:
                    node[index] = {}

            node = node[index]
        else:
            # Key step
            if not isinstance(node, dict):
                raise TypeError(f"expected dict at step, got {type(node).__name__}")

            if seg not in node:
                # Create missing container
                if is_next_index:
                    node[seg] = []
                else:
                    node[seg] = {}

            node = node[seg]

    # Handle the last segment (set the value)
    last_seg = segments[-1]
    if last_seg.startswith("["):
        index = int(last_seg[1:-1])
        if not isinstance(node, list):
            raise TypeError(f"expected list at final step, got {type(node).__name__}")

        if index == len(node):
            node.append(value)
        elif index > len(node):
            while len(node) < index:
                node.append(None)
            node.append(value)
        else:
            node[index] = value
    else:
        if not isinstance(node, dict):
            raise TypeError(f"expected dict at final step, got {type(node).__name__}")
        node[last_seg] = value

    return result
