def set_path(obj, path, value):
    """
    Returns a new structure where the location named by `path` holds `value`.
    The original `obj` and everything reachable from it is left untouched.

    Rules:
    - Path is dot-separated keys with optional list indexes (e.g., "a.b[2].c").
    - Missing dict keys are created as dicts.
    - Missing list containers are created as lists.
    - Index equal to list length appends.
    - Index > list length pads with None up to that index.
    - Type mismatch (key on list/scalar, index on dict/scalar) raises TypeError.
    - Empty, malformed paths or invalid indexes raise ValueError.
    - First step must be a key; obj must be a dict.
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or path.startswith(".") or path.startswith("["):
        raise ValueError("Path must be non-empty and start with a key")

    # Validate path format and parse steps
    steps = []
    current = ""
    i = 0
    while i < len(path):
        ch = path[i]
        if ch == '.':
            if current == "":
                raise ValueError(f"Malformed path: empty segment at position {i}")
            steps.append(('key', current))
            current = ""
        elif ch == '[':
            if current != "":
                steps.append(('key', current))
                current = ""
            # Find closing bracket
            j = i + 1
            while j < len(path) and path[j] != ']':
                if path[j] == '.':
                    raise ValueError(f"Malformed path: dot inside brackets at position {j}")
                j += 1
            if j >= len(path):
                raise ValueError(f"Malformed path: unclosed bracket starting at {i}")
            index_str = path[i+1:j]
            if not index_str:
                raise ValueError(f"Malformed path: empty index at position {i}")
            if not index_str.isdigit():
                raise ValueError(f"Malformed path: invalid index '{index_str}' at position {i}")
            steps.append(('index', int(index_str)))
            i = j
        else:
            current += ch
        i += 1

    if current != "":
        steps.append(('key', current))

    if not steps:
        raise ValueError("Path must contain at least one step")

    if steps[0][0] != 'key':
        raise ValueError("First step must be a key")

    def deep_copy(o):
        if isinstance(o, dict):
            return {k: deep_copy(v) for k, v in o.items()}
        elif isinstance(o, list):
            return [deep_copy(item) for item in o]
        else:
            return o

    result = deep_copy(obj)

    node = result
    # Navigate to the parent of the target location
    for step_type, step_val in steps[:-1]:
        if step_type == 'key':
            if isinstance(node, dict):
                if step_val not in node:
                    # Peek at next step to decide container type
                    next_type, _ = steps[steps.index((step_type, step_val)) + 1]
                    if next_type == 'index':
                        node[step_val] = []
                    else:
                        node[step_val] = {}
                node = node[step_val]
            elif isinstance(node, list):
                raise TypeError(f"Cannot use key '{step_val}' on a list")
            else:
                raise TypeError(f"Cannot use key '{step_val}' on a scalar")
        else:  # index
            idx = step_val
            if isinstance(node, list):
                if idx > len(node):
                    # Pad with None
                    node.extend([None] * (idx - len(node)))
                elif idx == len(node):
                    node.append(None)
                # Now node[idx] exists (might be None)
                if node[idx] is None:
                    # Peek at next step
                    next_type, _ = steps[steps.index((step_type, step_val)) + 1]
                    if next_type == 'index':
                        node[idx] = []
                    else:
                        node[idx] = {}
                node = node[idx]
            elif isinstance(node, dict):
                raise TypeError(f"Cannot use index {idx} on a dict")
            else:
                raise TypeError(f"Cannot use index {idx} on a scalar")

    # Set the final value
    last_type, last_val = steps[-1]
    if last_type == 'key':
        if isinstance(node, dict):
            node[last_val] = value
        elif isinstance(node, list):
            raise TypeError(f"Cannot use key '{last_val}' on a list")
        else:
            raise TypeError(f"Cannot use key '{last_val}' on a scalar")
    else:  # index
        idx = last_val
        if isinstance(node, list):
            if idx > len(node):
                node.extend([None] * (idx - len(node)))
            elif idx == len(node):
                node.append(value)
                return result
            node[idx] = value
        elif isinstance(node, dict):
            raise TypeError(f"Cannot use index {idx} on a dict")
        else:
            raise TypeError(f"Cannot use index {idx} on a scalar")

    return result
