def set_path(obj, path, value):
    """
    Set a value at a nested path in a dictionary, returning a new structure
    without modifying the original obj or anything reachable from it.

    Args:
        obj: The original dictionary (must be a dict)
        path: Dot-separated path with optional list indexes (e.g., "a.b[2].c")
        value: The value to set at the path

    Returns:
        A new dictionary with the value set at the specified path

    Raises:
        TypeError: If path step type mismatch or obj is not a dict
        ValueError: If path is empty or malformed
    """
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    if not path or not isinstance(path, str):
        raise ValueError("path must be a non-empty string")

    # Validate path format
    if path.startswith(".") or path.endswith("."):
        raise ValueError("path cannot start or end with a dot")
    if ".." in path:
        raise ValueError("path cannot contain empty segments")
    if "[." in path or ".[" in path.replace("[", ".["):
        # Check for patterns like "a.[0]" which would create empty segments
        pass

    def deep_copy(item):
        """Create a deep copy without sharing mutable parts."""
        if isinstance(item, dict):
            return {k: deep_copy(v) for k, v in item.items()}
        elif isinstance(item, list):
            return [deep_copy(v) for v in item]
        else:
            return item

    def parse_path(path_str):
        """Parse path string into list of (type, key) tuples."""
        parts = []
        current = ""
        i = 0
        while i < len(path_str):
            char = path_str[i]
            if char == '.':
                if current:
                    parts.append(('key', current))
                    current = ""
                i += 1
            elif char == '[':
                if current:
                    parts.append(('key', current))
                    current = ""
                # Find matching ]
                j = i + 1
                while j < len(path_str) and path_str[j] != ']':
                    j += 1
                if j >= len(path_str):
                    raise ValueError(f"malformed path: unclosed bracket at position {i}")
                index_str = path_str[i+1:j]
                if not index_str:
                    raise ValueError("malformed path: empty index")
                if index_str.startswith('-'):
                    raise ValueError("malformed path: negative index not allowed")
                try:
                    index = int(index_str)
                except ValueError:
                    raise ValueError(f"malformed path: invalid index '{index_str}'")
                parts.append(('index', index))
                i = j + 1
                # Check if next char is not end and not a dot
                if i < len(path_str) and path_str[i] != '.':
                    raise ValueError(f"malformed path: expected '.' after bracket at position {i-1}")
                if i < len(path_str):
                    i += 1  # skip the dot
            else:
                current += char
                i += 1

        if current:
            parts.append(('key', current))

        if not parts:
            raise ValueError("path must contain at least one segment")

        # First step must be a key
        if parts[0][0] != 'key':
            raise ValueError("first step must be a key")

        return parts

    def set_value_recursive(item, path_parts, path_index, value):
        """Recursively build new structure with value set at path."""
        if path_index >= len(path_parts):
            return value

        step_type, step_key = path_parts[path_index]

        if step_type == 'key':
            if isinstance(item, dict):
                new_dict = {}
                for k, v in item.items():
                    if k == step_key:
                        new_dict[k] = set_value_recursive(v, path_parts, path_index + 1, value)
                    else:
                        new_dict[k] = deep_copy(v)

                # If key doesn't exist, we need to create it
                if step_key not in item:
                    # Determine what to create based on next step
                    if path_index + 1 < len(path_parts):
                        next_type, _ = path_parts[path_index + 1]
                        if next_type == 'index':
                            new_dict[step_key] = set_value_recursive([], path_parts, path_index + 1, value)
                        else:
                            new_dict[step_key] = set_value_recursive({}, path_parts, path_index + 1, value)
                    else:
                        new_dict[step_key] = value

                return new_dict
            elif item is None or not isinstance(item, (dict, list)):
                # Replace scalar with appropriate container
                if path_index + 1 < len(path_parts):
                    next_type, _ = path_parts[path_index + 1]
                    if next_type == 'index':
                        new_dict = {step_key: set_value_recursive([], path_parts, path_index + 1, value)}
                    else:
                        new_dict = {step_key: set_value_recursive({}, path_parts, path_index + 1, value)}
                else:
                    new_dict = {step_key: value}
                return new_dict
            else:
                raise TypeError(f"cannot use key '{step_key}' on a list or scalar")

        else:  # step_type == 'index'
            if isinstance(item, list):
                new_list = [deep_copy(v) for v in item]

                # Handle index
                if step_key > len(new_list):
                    # Pad with None
                    while len(new_list) < step_key:
                        new_list.append(None)
                    new_list.append(None)  # Now len is step_key, append makes it step_key+1
                    # Actually, we need index step_key to exist
                    # If step_key == len, we append
                    # If step_key > len, we pad then set
                    new_list = [deep_copy(v) for v in item]
                    while len(new_list) <= step_key:
                        new_list.append(None)

                new_list[step_key] = set_value_recursive(
                    new_list[step_key] if step_key < len(new_list) else None,
                    path_parts, path_index + 1, value
                )

                return new_list
            elif item is None or not isinstance(item, (dict, list)):
                # Create new list
                new_list = [None] * (step_key + 1)
                new_list[step_key] = set_value_recursive(None, path_parts, path_index + 1, value)
                return new_list
            else:
                raise TypeError(f"cannot use index {step_key} on a dict or scalar")

    # Parse the path
    path_parts = parse_path(path)

    # Build new structure
    result = set_value_recursive(obj, path_parts, 0, value)

    return result
