        self.db_reads += 1
        return dict(self.db[uid])

    def _deep_copy(self, d):
        """Return a deep copy of a dict containing nested dicts."""
        result = {}
        for k, v in d.items():
            if isinstance(v, dict):
                result[k] = self._deep_copy(v)
            else:
                result[k] = v
        return result

    def get_profile(self, uid):
        if uid not in self.cache:
            self.cache[uid] = self._load(uid)
        # Return a deep copy so callers can mutate it without affecting the store or cache
        return self._deep_copy(self.cache[uid])

    def update_profile(self, uid, changes):
        if uid not in self.db:
            raise KeyError(uid)
        # Load current profile from DB (bypassing cache to ensure we have latest DB state)
        profile = self._load(uid)
        # Merge changes: new keys added, existing keys replaced, nested dicts replaced as a whole
        profile.update(changes)
        # Persist to DB
        self.db[uid] = profile
        # Invalidate cache so next get_profile triggers a fresh load from DB
        self.cache.pop(uid, None)
